INSERT INTO `materials` VALUES (1,'Gỗ MDF phủ Veneer','Gỗ công nghiệp MDF lõi xanh chống ẩm, phủ lớp Veneer vân gỗ tự nhiên. Chống cong vênh, mối mọt, bề mặt sáng bóng, dễ lau chùi.',1,'2025-07-08 20:33:52.838324','2025-07-08 20:33:52.838324'),(2,'Gỗ cao su tự nhiên','Gỗ cao su tự nhiên đã qua tẩm sấy, chống mối mọt. Độ bền cao, chịu lực tốt, vân gỗ đẹp, thân thiện với môi trường.',1,'2025-07-08 20:33:52.839499','2025-07-08 20:33:52.839499'),(3,'Kim loại sơn tĩnh điện','Kim loại (thường là sắt hoặc thép) được sơn tĩnh điện. Chống gỉ sét, trầy xước, độ bền cao, màu sắc đa dạng.',1,'2025-07-08 20:33:52.840517','2025-07-08 20:33:52.840517'),(4,'Vải bọc ghế','Vải bọc ghế polyester hoặc vải bố. Mềm mại, thoáng khí, chống bám bụi, dễ vệ sinh, màu sắc và hoa văn đa dạng.',1,'2025-07-08 20:33:52.841499','2025-07-08 20:33:52.841499'),(5,'Gỗ công nghiệp MDF phủ Veneer','Gỗ MDF chống ẩm, phủ lớp Veneer vân gỗ tự nhiên, tăng tính thẩm mỹ và độ bền. Bề mặt láng mịn, dễ dàng vệ sinh.',1,'2025-07-08 20:33:52.842995','2025-07-08 20:33:52.842995'),(6,'Da PU','Da PU mềm mại, êm ái, tạo cảm giác thoải mái khi ngồi. Dễ dàng vệ sinh và bảo quản, độ bền cao.',1,'2025-07-08 20:33:52.844351','2025-07-08 20:33:52.844351'),(7,'Gỗ Sồi','Gỗ sồi có độ bền cao, vân gỗ đẹp, khả năng chịu lực tốt, chống mối mọt tự nhiên. Được sử dụng cho khung bàn và chân ghế, đảm bảo sự chắc chắn và tuổi thọ sản phẩm.',1,'2025-07-08 20:33:52.845424','2025-07-08 20:33:52.845424'),(8,'Đá Tự Nhiên/Nhân Tạo','Mặt đá tự nhiên hoặc nhân tạo cao cấp có độ cứng cao, chống thấm, chịu nhiệt, dễ dàng vệ sinh. Mang đến vẻ đẹp sang trọng, hiện đại cho bàn ăn.',1,'2025-07-08 20:33:52.846853','2025-07-08 20:33:52.846853'),(9,'Sơn PU','Sơn PU cao cấp, không độc hại, có độ bóng mịn cao, chống trầy xước, bảo vệ bề mặt gỗ và đá, tăng tính thẩm mỹ cho sản phẩm.',1,'2025-07-08 20:33:52.848363','2025-07-08 20:33:52.848363'),(10,'Vải/Da (cho ghế)','Vải hoặc da bọc ghế cao cấp, thoáng khí, êm ái, dễ vệ sinh, tạo cảm giác thoải mái cho người sử dụng. Màu sắc đa dạng, phù hợp với nhiều phong cách nội thất.',1,'2025-07-08 20:33:52.849857','2025-07-08 20:33:52.849857'),(11,'Gỗ sồi tự nhiên','Gỗ sồi Nga nhập khẩu, đã qua tẩm sấy chống mối mọt, cong vênh. Vân gỗ đẹp, độ bền cao, chịu lực tốt, tạo vẻ đẹp tự nhiên và sang trọng.',1,'2025-07-08 20:33:52.850926','2025-07-08 20:33:52.850926'),(12,'Sơn PU cao cấp','Sơn PU (Polyurethane) không độc hại, an toàn cho sức khỏe. Tạo lớp bảo vệ bề mặt gỗ, chống thấm nước, chống trầy xước, dễ dàng vệ sinh và lau chùi.',1,'2025-07-08 20:33:52.851916','2025-07-08 20:33:52.851916'),(13,'Gỗ óc chó (màu sơn)','Màu sơn óc chó tạo vẻ sang trọng, ấm cúng cho sản phẩm, tôn lên vẻ đẹp tự nhiên của gỗ sồi.',1,'2025-07-08 20:33:52.852815','2025-07-08 20:33:52.852815'),(14,'Đá Tự Nhiên','Mặt đá tự nhiên với vân đá độc đáo, độ bền cao, khả năng chịu nhiệt tốt và dễ dàng vệ sinh.',1,'2025-07-08 20:33:52.853699','2025-07-08 20:33:52.853699'),(15,'Vải Bọc (Ghế)','Vải bọc ghế mềm mại, thoáng khí, tạo cảm giác thoải mái khi ngồi và dễ dàng vệ sinh.',1,'2025-07-08 20:33:52.854560','2025-07-08 20:33:52.854560'),(16,'Da PU (hoặc Nệm)','Sử dụng cho mặt ngồi ghế, tạo cảm giác êm ái, thoải mái khi sử dụng. Da PU dễ dàng vệ sinh và có độ bền tương đối.',1,'2025-07-08 20:33:52.855479','2025-07-08 20:33:52.855479'),(17,'Đá Tự Nhiên/Đá Nhân Tạo','Mặt đá có độ bền cao, chịu nhiệt tốt, dễ dàng vệ sinh và có vân đá độc đáo tạo vẻ sang trọng cho sản phẩm.',1,'2025-07-08 20:33:52.856360','2025-07-08 20:33:52.856360'),(18,'Gỗ Sồi (Oak)','Gỗ sồi tự nhiên với vân gỗ đẹp, độ bền cao, khả năng chịu lực tốt và chống mối mọt tự nhiên.',1,'2025-07-08 20:33:52.857496','2025-07-08 20:33:52.857496'),(19,'Da PU (Polyurethane)','Da PU cao cấp, mềm mại, dễ vệ sinh, chống thấm nước và có độ bền tương đối cao.',1,'2025-07-08 20:33:52.858458','2025-07-08 20:33:52.858458'),(20,'Sơn PU (Polyurethane)','Lớp sơn PU bảo vệ bề mặt gỗ, chống trầy xước, chống thấm nước và tăng độ bóng cho sản phẩm.',1,'2025-07-08 20:33:52.859344','2025-07-08 20:33:52.859344'),(21,'Gỗ cao su','Gỗ cao su đã qua xử lý chống cong vênh, mối mọt. Dùng làm khung ghế giúp sản phẩm chắc chắn.',1,'2025-07-08 20:33:52.860202','2025-07-08 20:33:52.860202'),(22,'Đá Khuân','Đá khuân tự nhiên, bề mặt chống thấm, dễ dàng vệ sinh, đường vân độc đáo tạo vẻ đẹp sang trọng.',1,'2025-07-08 20:33:52.861162','2025-07-08 20:33:52.861162'),(23,'Vải bọc ghế (Polyester)','Vải Polyester mềm mại, thoáng khí, độ bền cao, dễ dàng vệ sinh và bảo quản. Chống bám bụi và chống nhăn.',1,'2025-07-08 20:33:52.862231','2025-07-08 20:33:52.862231'),(24,'Kim loại (Thép)','Sử dụng cho phần khung chân bàn (nếu có) để tăng độ vững chãi và bền bỉ cho sản phẩm. Sơn tĩnh điện chống gỉ sét.',1,'2025-07-08 20:33:52.863172','2025-07-08 20:33:52.863172'),(25,'Đá Trắng (Nhân Tạo hoặc Tự Nhiên)','Mặt đá trắng có độ bền cao, chịu nhiệt tốt, dễ dàng vệ sinh, mang đến vẻ đẹp hiện đại và sang trọng cho bàn ăn.',1,'2025-07-08 20:33:52.864107','2025-07-08 20:33:52.864107'),(26,'Đá Nhân Tạo Cao Cấp','Đá nhân tạo với vân đá tự nhiên, khả năng chống thấm, chống trầy xước, dễ dàng vệ sinh, an toàn cho sức khỏe người sử dụng.',1,'2025-07-08 20:33:52.864928','2025-07-08 20:33:52.864928'),(27,'Bản Lề Kim Loại','Bản lề thép không gỉ, chịu lực tốt, đảm bảo cơ chế gấp gọn hoạt động trơn tru và bền bỉ.',1,'2025-07-08 20:33:52.865777','2025-07-08 20:33:52.865777'),(28,'Gỗ Xoan Đào','Gỗ tự nhiên có màu sắc ấm áp, vân gỗ đẹp, độ bền cao, khả năng chống mối mọt tốt. Thường được dùng trong sản xuất đồ nội thất cao cấp.',1,'2025-07-08 20:33:52.866629','2025-07-08 20:33:52.866629'),(29,'Da Simili/Nỉ','Vật liệu bọc ghế, tạo cảm giác êm ái, thoải mái khi ngồi. Da Simili dễ lau chùi, nỉ mang đến vẻ đẹp sang trọng, ấm áp.',1,'2025-07-08 20:33:52.867653','2025-07-08 20:33:52.867653'),(30,'Vải bọc cao cấp','Vải bố hoặc vải nhung, thoáng khí, mềm mại, có độ bền màu cao, chống bám bụi và dễ dàng vệ sinh.',1,'2025-07-08 20:33:52.868576','2025-07-08 20:33:52.868576'),(31,'Da công nghiệp','Da công nghiệp chất lượng cao, mềm mại, có độ bền cao, dễ dàng vệ sinh và mang lại vẻ sang trọng cho sản phẩm.',1,'2025-07-08 20:33:52.869451','2025-07-08 20:33:52.869451'),(32,'Mút D40','Mút D40 có độ đàn hồi cao, không bị xẹp lún sau thời gian dài sử dụng, mang lại cảm giác êm ái và thoải mái.',1,'2025-07-08 20:33:52.870256','2025-07-08 20:33:52.870256'),(33,'Vải Bọc Đệm','Vải bố hoặc vải nhung cao cấp, mềm mại, thoáng khí, chống bám bụi và dễ dàng vệ sinh. Đảm bảo sự thoải mái khi sử dụng.',1,'2025-07-08 20:33:52.871061','2025-07-08 20:33:52.871061'),(34,'Mút Đệm D40','Mút D40 có độ đàn hồi tốt, khả năng chịu lực cao, không bị xẹp lún sau thời gian dài sử dụng. Mang lại cảm giác êm ái, thoải mái.',1,'2025-07-08 20:33:52.871840','2025-07-08 20:33:52.871840'),(35,'Vải Nỉ','Vải nỉ cao cấp, mềm mại, thoáng khí, đa dạng màu sắc, dễ dàng vệ sinh, chống bám bụi, an toàn cho người sử dụng.',1,'2025-07-08 20:33:52.872826','2025-07-08 20:33:52.872826'),(36,'Vải nỉ/Da','Vải nỉ hoặc da cao cấp có độ mềm mại, êm ái, mang đến cảm giác thoải mái khi sử dụng. Có nhiều màu sắc và hoa văn để lựa chọn.',1,'2025-07-08 20:33:52.873806','2025-07-08 20:33:52.873806'),(37,'Gỗ công nghiệp MDF lõi xanh chống ẩm','Một số chi tiết phụ có thể được làm từ gỗ công nghiệp MDF lõi xanh chống ẩm, đảm bảo độ bền và khả năng chịu lực tốt trong môi trường có độ ẩm cao.',1,'2025-07-08 20:33:52.875607','2025-07-08 20:33:52.875607'),(38,'Gỗ công nghiệp MDF','Gỗ ép cao cấp, bề mặt phẳng mịn, chống cong vênh, phù hợp làm nội thất hiện đại.',1,'2025-07-08 20:33:52.876635','2025-07-08 20:33:52.876635'),(39,'Gỗ tự nhiên','Gỗ thật nguyên khối, vân gỗ tự nhiên đẹp, độ bền cao, mang lại cảm giác sang trọng.',1,'2025-07-08 20:33:52.877592','2025-07-08 20:33:52.877592'),(40,'Mặt đá nhân tạo (Solid Surface)','Chất liệu đá nhân tạo cao cấp, chống thấm, chịu nhiệt tốt, dễ dàng vệ sinh và đa dạng về màu sắc, vân đá.',1,'2025-07-08 20:33:52.878609','2025-07-08 20:33:52.878609'),(41,'Gỗ tự nhiên (gỗ sồi/tần bì)','Khung ghế được làm từ gỗ tự nhiên đã qua tẩm sấy kỹ lưỡng, chống mối mọt, đảm bảo độ bền chắc và tuổi thọ cao.',1,'2025-07-08 20:33:52.879566','2025-07-08 20:33:52.879566'),(42,'Vải nỉ cao cấp','Bề mặt sofa được bọc bằng vải nỉ mềm mại, thoáng khí, có độ bền cao và dễ dàng vệ sinh.',1,'2025-07-08 20:33:52.880521','2025-07-08 20:33:52.880521'),(43,'Lò xo thép','Hệ thống lò xo thép có độ đàn hồi cao, giúp phân bổ trọng lượng đều và tăng cường sự thoải mái khi ngồi.',1,'2025-07-08 20:33:52.881379','2025-07-08 20:33:52.881379'),(44,'Gỗ MDF phủ Melamine','Gỗ MDF (Medium-Density Fiberboard) lõi xanh chống ẩm, phủ Melamine chống trầy xước, chịu nhiệt, dễ vệ sinh và có tính thẩm mỹ cao.',1,'2025-07-08 20:33:52.882250','2025-07-08 20:33:52.882250'),(45,'Phụ kiện bản lề giảm chấn','Bản lề giảm chấn giúp đóng mở êm ái, không gây tiếng ồn và tăng tuổi thọ của sản phẩm.',1,'2025-07-08 20:33:52.883174','2025-07-08 20:33:52.883174'),(46,'Gỗ công nghiệp MDF phủ Melamine','Gỗ MDF lõi xanh chống ẩm, bề mặt phủ Melamine chống trầy xước, dễ lau chùi, đảm bảo tính thẩm mỹ và độ bền cao.',1,'2025-07-08 20:33:52.884063','2025-07-08 20:33:52.884063'),(47,'Gỗ tự nhiên (cao su/sồi)','Sử dụng cho chân bàn và khung gương, đã qua xử lý chống mối mọt, cong vênh, đảm bảo sự chắc chắn và tuổi thọ lâu dài.',1,'2025-07-08 20:33:52.884958','2025-07-08 20:33:52.884958'),(48,'Gương tráng bạc','Gương soi chất lượng cao, tráng bạc chống ố mốc, cho hình ảnh sắc nét và chân thực.',1,'2025-07-08 20:33:52.885864','2025-07-08 20:33:52.885864'),(49,'Kim loại (tay nắm)','Hợp kim kẽm mạ crom, chống gỉ sét, tăng tính thẩm mỹ và độ bền cho sản phẩm.',1,'2025-07-08 20:33:52.886763','2025-07-08 20:33:52.886763'),(50,'Kính','Kính tráng bạc cao cấp, cho hình ảnh phản chiếu sắc nét, chân thực, không bị ố vàng theo thời gian, độ bền cao.',1,'2025-07-08 20:33:52.887756','2025-07-08 20:33:52.887756'),(51,'Kim loại (Hợp kim)','Hợp kim kẽm mạ chrome, chống gỉ sét, độ bền cao, tạo điểm nhấn sang trọng cho sản phẩm (tay nắm, chân bàn...).',1,'2025-07-08 20:33:52.888755','2025-07-08 20:33:52.888755'),(52,'Kính (nếu có)','Kính cường lực (tùy chọn) cho cánh tủ, tăng tính thẩm mỹ và an toàn khi sử dụng.',1,'2025-07-08 20:33:52.889705','2025-07-08 20:33:52.889705'),(53,'Kính cường lực','Kính cường lực dày 5mm-8mm, đảm bảo an toàn khi vỡ, chịu lực tốt, tăng tính thẩm mỹ và dễ dàng vệ sinh.',1,'2025-07-08 20:33:52.890587','2025-07-08 20:33:52.890587'),(54,'Bản lề giảm chấn','Bản lề thép không gỉ, tích hợp giảm chấn giúp đóng mở cửa nhẹ nhàng, êm ái và tăng độ bền cho tủ.',1,'2025-07-08 20:33:52.891415','2025-07-08 20:33:52.891415'),(55,'Kim loại (thép không gỉ)','Sử dụng cho bản lề và tay nắm, thép không gỉ đảm bảo độ bền, chống ăn mòn và tính thẩm mỹ cao.',1,'2025-07-08 20:33:52.892398','2025-07-08 20:33:52.892398'),(56,'Gỗ MDF chống ẩm','Gỗ MDF lõi xanh chống ẩm, bề mặt phủ Melamine hoặc Veneer. Độ bền cao, không cong vênh, chịu lực tốt, dễ dàng vệ sinh và chống mối mọt.',1,'2025-07-08 20:33:52.893295','2025-07-08 20:33:52.893295'),(57,'Kim loại (bản lề, khóa)','Bản lề và khóa kim loại không gỉ, đảm bảo độ bền và an toàn khi sử dụng.',1,'2025-07-08 20:33:52.894193','2025-07-08 20:33:52.894193'),(58,'Gỗ Sồi Nga','Gỗ sồi Nga có vân gỗ đẹp, độ cứng cao, khả năng chịu lực tốt, ít bị cong vênh và chống mối mọt tự nhiên. Thường được dùng làm khung và cánh tủ.',1,'2025-07-08 20:33:52.894997','2025-07-08 20:33:52.894997'),(59,'Gỗ MDF lõi xanh chống ẩm','Gỗ MDF lõi xanh chống ẩm có khả năng chịu ẩm tốt, bề mặt phẳng mịn, dễ dàng sơn phủ. Thường được dùng làm vách ngăn, đáy tủ và hậu tủ.',1,'2025-07-08 20:33:52.895812','2025-07-08 20:33:52.895812'),(60,'Kính trong suốt','Kính trong suốt giúp dễ dàng quan sát các vật dụng bên trong tủ, tăng tính thẩm mỹ và tiện lợi khi sử dụng.',1,'2025-07-08 20:33:52.896711','2025-07-08 20:33:52.896711');
/*!40000 ALTER TABLE `materials` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `order_tracking_logs`
--

DROP TABLE IF EXISTS `order_tracking_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_tracking_logs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `order_id` int NOT NULL,
  `message` text NOT NULL,
  `created_by_id` int NOT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  KEY `IDX_65e38076c71146cc353962526f` (`created_at`),
  KEY `IDX_8a44ad6cd78bdf08a2f77e8d7a` (`created_by_id`),
  KEY `IDX_4f3f3d811c588f80d909e59edd` (`order_id`),
  CONSTRAINT `FK_4f3f3d811c588f80d909e59edd8` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE,
  CONSTRAINT `FK_8a44ad6cd78bdf08a2f77e8d7a3` FOREIGN KEY (`created_by_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

