/*!40000 ALTER TABLE `products` DISABLE KEYS */;
INSERT INTO `products` VALUES (1,'Bàn Ăn + 4 Ghế Nhập Khẩu 4 Ghế  GX-01','Bàn Ăn + 4 Ghế Nhập Khẩu GX-01 là sự kết hợp hoàn hảo giữa thiết kế hiện đại và chất lượng vượt trội, mang đến không gian ăn uống ấm cúng và sang trọng cho gia đình bạn. Bộ sản phẩm bao gồm một bàn ăn hình chữ nhật với mặt bàn rộng rãi và 4 ghế ngồi thoải mái, được nhập khẩu nguyên bộ, đảm bảo độ bền và tính thẩm mỹ cao.\n\nThiết kế của bộ bàn ăn GX-01 tập trung vào sự đơn giản, tinh tế nhưng vẫn toát lên vẻ sang trọng. Bàn ăn có mặt bàn trơn láng, các góc cạnh được bo tròn mềm mại, an toàn cho người sử dụng, đặc biệt là trẻ em. Ghế ăn được thiết kế với lưng tựa cong nhẹ, ôm sát cơ thể, tạo cảm giác thoải mái khi ngồi. Chân bàn và chân ghế được thiết kế chắc chắn, đảm bảo sự ổn định và an toàn trong quá trình sử dụng.\n\nBộ bàn ăn GX-01 được chế tạo từ các vật liệu cao cấp, được xử lý kỹ lưỡng bằng công nghệ hiện đại. Mặt bàn thường được làm từ gỗ công nghiệp MDF phủ veneer vân gỗ tự nhiên hoặc gỗ tự nhiên nguyên khối, chống thấm nước, chống trầy xước và dễ dàng vệ sinh. Khung chân bàn và ghế thường được làm từ gỗ tự nhiên đã qua tẩm sấy hoặc kim loại sơn tĩnh điện, đảm bảo độ bền và khả năng chịu lực cao.\n\nVới kích thước vừa phải, bộ bàn ăn GX-01 phù hợp với nhiều không gian bếp và phòng ăn khác nhau, từ căn hộ chung cư đến nhà phố. Màu sắc trang nhã, dễ dàng phối hợp với các đồ nội thất khác, tạo nên một không gian sống hài hòa và đẹp mắt.\n\nBộ bàn ăn GX-01 không chỉ là nơi cả gia đình quây quần bên nhau thưởng thức những bữa ăn ngon mà còn là điểm nhấn ấn tượng, thể hiện gu thẩm mỹ tinh tế của gia chủ. Sản phẩm mang đến sự tiện nghi, thoải mái và góp phần nâng cao chất lượng cuộc sống của bạn.',2,'https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Ăn Nhập Khẩu/438031910_1380209809341531_5221607147034668979_n-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Ăn Nhập Khẩu/434843870_1380208752674970_7537791474422663805_n-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Ăn Nhập Khẩu/437374959_1380209909341521_9145190862512965494_n-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Ăn Nhập Khẩu/438031910_1380209809341531_5221607147034668979_n-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Ăn Nhập Khẩu/438032089_1380209876008191_5753499024266368181_n-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Ăn Nhập Khẩu/z5408078823077_db2835e6d8f4bddc42473d6516a81e61-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Ăn Nhập Khẩu/z5408078829241_48701ab5f56c792dc18c94b954243d3a-500x500.jpg',2850000.00,1,'2025-07-08 20:33:53.006056','2025-07-08 20:33:53.006056'),(2,'Bàn Ăn + 6 Ghế  Nhập Khẩu GX-01','Bộ bàn ăn nhập khẩu GX-01 mang đến sự sang trọng và tinh tế cho không gian bếp hoặc phòng ăn của bạn. Thiết kế hiện đại với những đường nét tối giản, thanh lịch, phù hợp với nhiều phong cách nội thất khác nhau. Mặt bàn được làm từ gỗ công nghiệp cao cấp phủ veneer vân gỗ tự nhiên, tạo cảm giác ấm cúng và gần gũi. Khung bàn và chân ghế được chế tác từ kim loại sơn tĩnh điện, đảm bảo độ bền và khả năng chịu lực tốt. Ghế ăn được bọc da PU êm ái, mang lại sự thoải mái tối đa cho người sử dụng. \n\nBộ sản phẩm này không chỉ là nơi cả gia đình quây quần bên nhau thưởng thức những bữa ăn ngon, mà còn là điểm nhấn ấn tượng, thể hiện gu thẩm mỹ tinh tế của gia chủ. Với thiết kế 6 ghế, bộ bàn ăn GX-01 đáp ứng nhu cầu sử dụng của gia đình có từ 4-6 thành viên, hoặc khi có khách đến chơi nhà. Kích thước bàn được thiết kế hợp lý, không chiếm quá nhiều diện tích, phù hợp với cả những không gian vừa và nhỏ. \n\nCông nghệ sản xuất hiện đại giúp sản phẩm có độ hoàn thiện cao, các chi tiết được gia công tỉ mỉ. Bề mặt dễ dàng vệ sinh, lau chùi, giúp bạn tiết kiệm thời gian và công sức. Chọn bộ bàn ăn GX-01, bạn không chỉ sở hữu một sản phẩm nội thất chất lượng mà còn đầu tư vào sự tiện nghi và vẻ đẹp cho ngôi nhà của mình. Sản phẩm phù hợp với phong cách nội thất hiện đại, tối giản, Scandinavian, hoặc Japandi.',2,'https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Ăn Nhập Khẩu/GX001 6 ghế/z5408083658696_ed6f8e02af071d1c1e103846d3c04656-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Ăn Nhập Khẩu/GX001 6 ghế/z5408083663125_591186482ff6e6ccefde7f74db8595c9-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Ăn Nhập Khẩu/GX001 6 ghế/z5408083658696_ed6f8e02af071d1c1e103846d3c04656-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Ăn Nhập Khẩu/GX001 6 ghế/387085438_632827768966221_560445600537734530_n-500x500.jpg',4450000.00,1,'2025-07-08 20:33:53.007696','2025-07-08 20:33:53.007696'),(3,'Bàn Ăn Gỗ Sồi Chân C  Mặt Đá 6 Ghế Màu Óc Chó','Bàn ăn gỗ sồi chân chữ C mặt đá 6 ghế màu óc chó là sự kết hợp hoàn hảo giữa vẻ đẹp hiện đại, sang trọng và sự ấm cúng, gần gũi của chất liệu tự nhiên. Thiết kế chân chữ C độc đáo không chỉ tạo điểm nhấn ấn tượng mà còn mang đến sự vững chãi, chắc chắn cho bàn ăn. Mặt bàn đá tự nhiên hoặc đá nhân tạo cao cấp với bề mặt sáng bóng, dễ dàng vệ sinh, chống thấm nước và chịu nhiệt tốt. \n\nSáu chiếc ghế ăn được thiết kế đồng bộ với bàn, sở hữu kiểu dáng thanh lịch, đường nét tinh tế và được phủ lớp sơn màu óc chó trầm ấm, tạo nên sự hài hòa, đồng điệu cho không gian phòng ăn. Lưng ghế được thiết kế cong nhẹ, ôm sát cơ thể, kết hợp cùng đệm ngồi êm ái, mang lại cảm giác thoải mái cho người sử dụng trong suốt bữa ăn. \n\nBộ bàn ăn này không chỉ là nơi cả gia đình quây quần bên nhau thưởng thức những bữa cơm ngon, mà còn là điểm nhấn trang trí, thể hiện gu thẩm mỹ tinh tế của gia chủ. Với kích thước rộng rãi, bàn ăn phù hợp với nhiều không gian phòng ăn khác nhau, từ căn hộ chung cư đến nhà phố, biệt thự. Phong cách thiết kế hiện đại pha chút cổ điển giúp bộ bàn ăn dễ dàng hòa nhập với nhiều phong cách nội thất khác nhau, từ Scandinavian tối giản đến phong cách tân cổ điển sang trọng. \n\nSở hữu bộ bàn ăn gỗ sồi chân chữ C mặt đá 6 ghế màu óc chó, bạn không chỉ có được một sản phẩm nội thất chất lượng cao, bền đẹp mà còn nâng tầm không gian sống, mang đến những trải nghiệm tuyệt vời cho cả gia đình.',2,'https://goxinh.com.vn/image/cache/Ban-ghe-an/314411776_2920827428225398_6073788091019514373_n-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/314419207_2920827458225395_2128435082097592709_n-500x500.jpg',9950000.00,1,'2025-07-08 20:33:53.008802','2025-07-08 20:33:53.008802'),(4,'Bàn Ăn Gỗ Sồi Chân C Mặt Gỗ 6 Ghê','Bàn ăn gỗ sồi chân chữ C mặt gỗ với 6 ghế là sự lựa chọn hoàn hảo cho không gian bếp ăn hiện đại và ấm cúng. Thiết kế tối giản, tinh tế với phần chân bàn hình chữ C độc đáo, tạo điểm nhấn ấn tượng và mang đến sự vững chãi tuyệt đối. Mặt bàn được làm từ gỗ sồi tự nhiên, vân gỗ đẹp mắt, được xử lý kỹ lưỡng để chống thấm nước, chống trầy xước và dễ dàng vệ sinh. Bộ 6 ghế đi kèm được thiết kế đồng bộ với bàn, mang đến sự hài hòa và thoải mái cho người sử dụng. \n\nKiểu dáng hiện đại của bộ bàn ăn này phù hợp với nhiều phong cách nội thất khác nhau, từ phong cách Scandinavian tối giản đến phong cách hiện đại sang trọng. Với kích thước vừa phải, bộ bàn ăn này phù hợp với các căn hộ chung cư hoặc nhà phố có diện tích vừa và nhỏ. Khả năng sử dụng linh hoạt, phục vụ tốt cho các bữa ăn gia đình hàng ngày hoặc các buổi tiệc nhỏ với bạn bè.\n\nSản phẩm được sản xuất trên dây chuyền công nghệ hiện đại, đảm bảo độ bền đẹp và tuổi thọ lâu dài. Gỗ sồi tự nhiên được tẩm sấy kỹ càng, chống mối mọt và cong vênh. Bề mặt gỗ được phủ lớp sơn PU cao cấp, không độc hại, an toàn cho sức khỏe người sử dụng.\n\nBộ bàn ăn gỗ sồi chân chữ C không chỉ là nơi để cả gia đình quây quần bên nhau thưởng thức những bữa ăn ngon mà còn là điểm nhấn thẩm mỹ, mang đến sự ấm áp và sang trọng cho không gian sống của bạn. Đầu tư vào bộ bàn ăn này là đầu tư vào chất lượng cuộc sống và hạnh phúc gia đình.',2,'https://goxinh.com.vn/image/cache/Ban-ghe-an/313428202_2920827311558743_1949299179374564132_n-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/GS chân C/z4711730894864_5ad6f5c26d385394050be8a6bb904ff1-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/GS chân C/z4915900901055_e677d36509a52eeb270137c98c973a14-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/313428202_2920827311558743_1949299179374564132_n-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/GS chân C/z5420557442968_aec66ea79032c9195a91d4a50ce8d617-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/GS chân C/z5420557456019_7ff7b2904047f8299673264e769b73db-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/GS chân C/z5420557462506_bde83c8718142794dd78f1708e1184a7-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/GS chân C/z5420557506516_6ae7c543a1afef5954715739b27decf6-500x500.jpg',9950000.00,1,'2025-07-08 20:33:53.009876','2025-07-08 20:33:53.009876'),(5,'Bàn Ăn Gỗ Sồi Chân Côn 6 ghế 2 Tựa Ngang','Bàn ăn gỗ sồi chân côn 6 ghế 2 tựa ngang là sự kết hợp hoàn hảo giữa nét đẹp truyền thống và phong cách hiện đại, mang đến không gian ấm cúng và sang trọng cho phòng bếp của bạn. Thiết kế chân côn thon gọn, thanh thoát tạo cảm giác nhẹ nhàng, tinh tế, đồng thời đảm bảo độ vững chắc và chịu lực tốt. Mặt bàn gỗ sồi tự nhiên được xử lý kỹ lưỡng, chống thấm nước và dễ dàng vệ sinh, giữ cho bàn luôn sáng bóng và bền đẹp theo thời gian. Điểm nhấn của bộ bàn ăn nằm ở 2 ghế tựa ngang độc đáo, tạo sự khác biệt và tăng thêm tính thẩm mỹ cho không gian. \n\nBộ bàn ăn này không chỉ là nơi gia đình sum vầy bên những bữa cơm ngon mà còn là điểm nhấn ấn tượng, thể hiện gu thẩm mỹ tinh tế của gia chủ. Thiết kế đơn giản nhưng không kém phần sang trọng giúp bộ bàn ăn dễ dàng hòa hợp với nhiều phong cách nội thất khác nhau, từ hiện đại, tối giản đến Scandinavian hay Rustic. Với kích thước phù hợp cho 6 người ngồi, bộ bàn ăn gỗ sồi này là lựa chọn lý tưởng cho các gia đình trẻ hoặc những ai yêu thích sự ấm cúng, thân thiện.\n\nQuy trình sản xuất tỉ mỉ, kết hợp công nghệ hiện đại và kinh nghiệm lâu năm của các nghệ nhân, đảm bảo chất lượng sản phẩm hoàn hảo đến từng chi tiết. Bàn ăn được phủ lớp sơn PU cao cấp, không chỉ bảo vệ bề mặt gỗ mà còn làm nổi bật vẻ đẹp tự nhiên của vân gỗ sồi. Sự kết hợp hài hòa giữa chất liệu gỗ tự nhiên cao cấp và thiết kế tinh tế, hiện đại, hứa hẹn mang đến cho bạn những trải nghiệm tuyệt vời trong mỗi bữa ăn.',2,'https://goxinh.com.vn/image/cache/Ban-ghe-an/z3443161737854_650abc30cc16a896f7fa5bd4b80abc23-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/280116707_771903514186717_1160692553172474478_n-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/276151762_518930143002724_352334112156511166_n-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/z3443161737854_650abc30cc16a896f7fa5bd4b80abc23-500x500.jpg',7850000.00,1,'2025-07-08 20:33:53.010838','2025-07-08 20:33:53.010838'),(6,'Bàn Ăn Gỗ Sồi Chân Hươu  6 ghế 1 Tựa Ngang','Bàn Ăn Gỗ Sồi Chân Hươu 6 ghế 1 Tựa Ngang là sự kết hợp hoàn hảo giữa vẻ đẹp tự nhiên, sự sang trọng và tính tiện dụng, mang đến không gian ấm cúng và tinh tế cho phòng ăn của bạn. Thiết kế chân bàn được lấy cảm hứng từ hình ảnh đôi chân hươu thon gọn, vững chãi, tạo nên sự độc đáo và thu hút. Mặt bàn gỗ sồi nguyên khối được xử lý tỉ mỉ, giữ nguyên vẻ đẹp vân gỗ tự nhiên, mang đến cảm giác gần gũi với thiên nhiên. \n\nBàn ăn được sản xuất từ gỗ sồi tự nhiên, trải qua quy trình tẩm sấy hiện đại, đảm bảo độ bền cao, khả năng chống mối mọt và cong vênh. Bề mặt bàn được phủ lớp sơn PU cao cấp, chống trầy xước và dễ dàng vệ sinh. Bộ 6 ghế đi kèm được thiết kế đồng bộ với bàn ăn, tựa lưng ngang tạo sự thoải mái tối đa cho người sử dụng. \n\nVới kích thước rộng rãi, bàn ăn phù hợp cho gia đình 6 người, tạo không gian thoải mái để thưởng thức những bữa ăn ngon. Bàn ăn Gỗ Sồi Chân Hươu là lựa chọn lý tưởng cho những không gian nội thất mang phong cách hiện đại, tối giản hoặc Scandinavian. Sản phẩm không chỉ là nơi sum họp gia đình mà còn là điểm nhấn độc đáo, thể hiện gu thẩm mỹ tinh tế của gia chủ. Sự vững chắc, bền bỉ và vẻ đẹp tự nhiên của gỗ sồi sẽ mang đến cho bạn một sản phẩm chất lượng, sử dụng lâu dài và không bao giờ lỗi mốt.',2,'https://goxinh.com.vn/image/cache/Ban-ghe-an/279913683_771903460853389_4287690084417685899_n-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/GS 6 ghế 1 tựa + 2 tựa /z5420557442658_10955a79589aadef46d902c3603eb842-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/GS 6 ghế 1 tựa + 2 tựa /z5420557454534_aec2d9da3a05eba1cb2864d02d8936b1-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/GS 6 ghế 1 tựa + 2 tựa /z5420557395339_8cbc58603d80ae3b1a3466bc1a75fb82-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/GS 6 ghế 1 tựa + 2 tựa /z5420557395341_3c5d2048ac793d843510515fc10e0bc0-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/279913683_771903460853389_4287690084417685899_n-500x500.jpg',7850000.00,1,'2025-07-08 20:33:53.012142','2025-07-08 20:33:53.012142'),(7,'Bàn Ăn Gỗ Sồi Chân Hươu Mặt Gỗ 6 Ghế Màu Óc','Bàn ăn gỗ sồi chân hươu mặt gỗ 6 ghế màu óc chó là sự kết hợp hoàn hảo giữa vẻ đẹp tự nhiên, sự tinh tế trong thiết kế và độ bền vượt trội. Mặt bàn được chế tác từ gỗ sồi nguyên khối, nổi bật với những đường vân gỗ độc đáo và màu sắc ấm áp của óc chó, mang đến cảm giác sang trọng và gần gũi cho không gian bếp hoặc phòng ăn. Thiết kế chân bàn hình hươu, được lấy cảm hứng từ vẻ đẹp thanh thoát và mạnh mẽ của loài vật này, không chỉ tạo điểm nhấn độc đáo mà còn đảm bảo sự vững chắc và ổn định cho bàn. \n\nBộ bàn ăn này được sản xuất trên dây chuyền công nghệ hiện đại, trải qua quy trình xử lý tẩm sấy kỹ lưỡng, chống mối mọt và cong vênh, đảm bảo tuổi thọ lâu dài. Lớp sơn phủ PU cao cấp không chỉ bảo vệ bề mặt gỗ khỏi trầy xước, thấm nước mà còn tạo độ bóng mịn, dễ dàng vệ sinh và lau chùi. \n\nVới kích thước phù hợp, bàn ăn có thể thoải mái phục vụ cho gia đình 6 người. Kiểu dáng thanh lịch và hiện đại của bộ bàn ăn dễ dàng hòa hợp với nhiều phong cách nội thất khác nhau, từ cổ điển đến hiện đại, từ tối giản đến tân cổ điển. \n\nSở hữu bộ bàn ăn gỗ sồi chân hươu mặt gỗ 6 ghế màu óc chó không chỉ mang đến một không gian ăn uống ấm cúng và sang trọng mà còn là sự đầu tư thông minh cho sức khỏe và sự thoải mái của cả gia đình. Bữa cơm gia đình sẽ trở nên trọn vẹn và ý nghĩa hơn bao giờ hết bên chiếc bàn ăn được thiết kế tỉ mỉ và chất lượng này.',2,'https://goxinh.com.vn/image/cache/Ban-ghe-an/z3881910448516_607a6b6f7906cbfeea1758bf8f6e759b-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/GS 6 ghế 1 tựa + 2 tựa /z5420557442658_10955a79589aadef46d902c3603eb842-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/GS 6 ghế 1 tựa + 2 tựa /z5070435351212_6b55d5b54b7e66cd99beb1f3d68151ce-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/GS 6 ghế 1 tựa + 2 tựa /z5095521912200_46b2e16365046919b1350b1f7cd6d844-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/GS 6 ghế 1 tựa + 2 tựa /z5018517487137_1ae881fa8d472582e565ae4763a3a69c-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/z3881910448516_607a6b6f7906cbfeea1758bf8f6e759b-500x500.jpg',8600000.00,1,'2025-07-08 20:33:53.015687','2025-07-08 20:33:53.015687'),(8,'Bàn Ăn Gỗ Sồi Chân Hươu Mặt Đá 4 Ghế Màu Óc Chó','Bàn ăn gỗ sồi chân hươu mặt đá 4 ghế màu óc chó là sự kết hợp hoàn hảo giữa vẻ đẹp tự nhiên, sự sang trọng và độ bền bỉ. Thiết kế chân hươu độc đáo tạo điểm nhấn ấn tượng, mang đến sự thanh thoát và tinh tế cho không gian bếp hoặc phòng ăn. Mặt bàn đá tự nhiên với vân đá độc nhất vô nhị không chỉ tăng thêm vẻ đẹp thẩm mỹ mà còn đảm bảo độ bền, khả năng chịu nhiệt và dễ dàng vệ sinh. Màu óc chó ấm áp của ghế tạo sự hài hòa và ấm cúng cho tổng thể bộ bàn ăn. \n\nBàn ăn được chế tác từ gỗ sồi tự nhiên đã qua xử lý kỹ lưỡng, đảm bảo khả năng chống cong vênh, mối mọt và chịu lực tốt. Công nghệ sơn PU cao cấp giúp bảo vệ bề mặt gỗ, tăng độ bền màu và dễ dàng lau chùi. Mặt đá tự nhiên được gia công tỉ mỉ, bo tròn các cạnh để đảm bảo an toàn cho người sử dụng. \n\nVới kích thước phù hợp cho 4 người, bộ bàn ăn này là lựa chọn lý tưởng cho các gia đình nhỏ hoặc căn hộ chung cư. Phong cách thiết kế hiện đại pha lẫn nét cổ điển giúp bộ bàn ăn dễ dàng hòa nhập với nhiều phong cách nội thất khác nhau, từ phong cách Scandinavian tối giản đến phong cách tân cổ điển sang trọng. \n\nSở hữu bộ bàn ăn gỗ sồi chân hươu mặt đá 4 ghế màu óc chó, bạn không chỉ có một sản phẩm nội thất chất lượng mà còn tạo nên một không gian ăn uống ấm cúng, sang trọng và tiện nghi, nơi cả gia đình có thể quây quần bên nhau sau một ngày dài.',2,'https://goxinh.com.vn/image/cache/Ban-ghe-an/z3286576866319_1b427e4fe97edbd79ab15f176fc18211-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/z3286576866319_1b427e4fe97edbd79ab15f176fc18211-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Gỗ Sồi 4 ghế/z5420557389558_2f3de0e4af892e0cab06d6bfe52224b8-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Gỗ Sồi 4 ghế/z5420557509778_7d71280c22466bbffff93b772c199beb-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Gỗ Sồi 4 ghế/z5420557443430_0451f4b1eb50496f9e30c7f5d202b08b-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Gỗ Sồi 4 ghế/z5420557438810_7304bba12c8e460c8467370eed6086e6-500x500.jpg',6500000.00,1,'2025-07-08 20:33:53.016778','2025-07-08 20:33:53.016778'),(9,'Bàn Ăn Gỗ Sồi Chân Hươu Mặt Đá 6 Ghế Màu Hương','Bàn ăn gỗ sồi chân hươu mặt đá 6 ghế màu hương là sự kết hợp tinh tế giữa vẻ đẹp tự nhiên và sự sang trọng hiện đại, mang đến không gian ấm cúng và đẳng cấp cho phòng bếp của bạn. Thiết kế chân hươu độc đáo, uyển chuyển không chỉ tạo điểm nhấn thẩm mỹ mà còn đảm bảo sự vững chắc và ổn định cho bàn. Mặt đá tự nhiên với vân đá độc đáo, chống thấm, chịu nhiệt tốt, dễ dàng vệ sinh và bảo quản. Màu hương ấm áp của gỗ sồi tự nhiên tạo cảm giác gần gũi, thân thiện và sang trọng. \n\nBộ bàn ăn gồm 6 ghế được thiết kế đồng bộ với bàn, mang đến sự hài hòa và cân đối cho tổng thể không gian. Ghế có tựa lưng thoải mái, mặt ngồi bọc da hoặc nệm êm ái, tạo cảm giác dễ chịu cho người sử dụng. \n\nSản phẩm được sản xuất trên dây chuyền công nghệ hiện đại, đảm bảo độ chính xác và hoàn thiện cao. Gỗ sồi được xử lý kỹ lưỡng, chống mối mọt, cong vênh, đảm bảo độ bền và tuổi thọ lâu dài. Mặt đá được lựa chọn kỹ càng, đảm bảo chất lượng và tính thẩm mỹ. \n\nBàn ăn gỗ sồi chân hươu mặt đá 6 ghế màu hương không chỉ là nơi cả gia đình sum họp bên những bữa cơm ngon mà còn là điểm nhấn ấn tượng cho không gian bếp, thể hiện gu thẩm mỹ tinh tế của gia chủ. Phù hợp với nhiều phong cách nội thất khác nhau, từ cổ điển đến hiện đại, từ tối giản đến sang trọng. \n\nVới kích thước rộng rãi, bộ bàn ăn này phù hợp cho gia đình từ 4-6 người, đáp ứng nhu cầu sử dụng hàng ngày cũng như những buổi tiệc nhỏ. Dễ dàng lau chùi, bảo quản, giúp bạn tiết kiệm thời gian và công sức. Sở hữu bộ bàn ăn này, bạn sẽ có một không gian bếp ấm cúng, sang trọng và tiện nghi, nơi cả gia đình có thể tận hưởng những khoảnh khắc ý nghĩa bên nhau.',2,'https://goxinh.com.vn/image/cache/Ban-ghe-an/z3270798574459_542e88ee7d81f2e42d0ccb8808015b3d-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/z3270798574459_542e88ee7d81f2e42d0ccb8808015b3d-500x500.jpg',8600000.00,1,'2025-07-08 20:33:53.019792','2025-07-08 20:33:53.019792'),(10,'Bàn Ăn Gỗ Sồi Chân Hươu Mặt Đá 6 Ghế Màu Óc','Bàn ăn gỗ sồi chân hươu mặt đá 6 ghế màu óc chó là sự kết hợp tinh tế giữa vẻ đẹp tự nhiên và phong cách hiện đại. Thiết kế chân hươu độc đáo, uyển chuyển mang đến sự thanh thoát và vững chắc cho bàn ăn. Mặt đá tự nhiên hoặc đá nhân tạo cao cấp với vân đá độc đáo không chỉ tăng tính thẩm mỹ mà còn đảm bảo độ bền, khả năng chịu nhiệt và dễ dàng vệ sinh. Màu óc chó trầm ấm mang lại cảm giác sang trọng và gần gũi, phù hợp với nhiều không gian nội thất. \n\nSản phẩm được chế tác từ gỗ sồi tự nhiên đã qua xử lý kỹ lưỡng, đảm bảo khả năng chống mối mọt, cong vênh và tuổi thọ lâu dài. Công nghệ sơn PU cao cấp giúp bảo vệ bề mặt gỗ, tăng độ bóng và chống trầy xước. Kết hợp với 6 ghế tựa lưng thoải mái, bàn ăn này là lựa chọn lý tưởng cho những bữa cơm gia đình ấm cúng hoặc những buổi tiệc nhỏ cùng bạn bè. \n\nBàn ăn gỗ sồi chân hươu mặt đá không chỉ là một món đồ nội thất mà còn là điểm nhấn cho không gian bếp hoặc phòng ăn của bạn. Với kích thước vừa phải, sản phẩm phù hợp với nhiều diện tích khác nhau, từ căn hộ chung cư đến nhà phố. Phong cách thiết kế này dễ dàng hòa nhập với các phong cách nội thất hiện đại, tối giản hoặc tân cổ điển. \n\nLựa chọn bàn ăn gỗ sồi chân hươu mặt đá là bạn đang đầu tư vào sự tiện nghi, thẩm mỹ và độ bền cho không gian sống của mình. Sản phẩm này sẽ mang đến những trải nghiệm tuyệt vời cho bạn và gia đình trong mỗi bữa ăn.',2,'https://goxinh.com.vn/image/cache/Ban-ghe-an/z3270798563095_e035b3db48d13e4554fd9ff92606c471-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/z3270798563095_e035b3db48d13e4554fd9ff92606c471-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Giao Khách/z4806306883844_55eb5754ec89d14a6f41c14f1eae72f4-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Giao Khách/z4806306937049_93294087933da0aadb576b5097160e5d-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Giao Khách/z4806367811846_ae18d25178bb0dc5dca80a57be0bf3d0-500x500.jpg',8600000.00,1,'2025-07-08 20:33:53.020831','2025-07-08 20:33:53.020831'),(11,'Bàn Ăn Gỗ Sồi Chân X 6 Ghế Ghế Màu Óc Chó','Bàn ăn gỗ sồi chân chữ X kết hợp cùng 6 ghế tựa bọc da màu óc chó là sự lựa chọn hoàn hảo cho không gian bếp ăn hiện đại và ấm cúng. Thiết kế bàn đơn giản nhưng tinh tế với mặt bàn gỗ sồi tự nhiên được xử lý tỉ mỉ, giữ nguyên vẻ đẹp vân gỗ độc đáo. Chân bàn hình chữ X tạo sự vững chãi và tăng tính thẩm mỹ cho tổng thể sản phẩm. Ghế ăn được thiết kế với phần lưng tựa cong nhẹ, ôm sát cơ thể, mang lại cảm giác thoải mái khi ngồi. Chất liệu da bọc màu óc chó sang trọng, dễ dàng vệ sinh và phù hợp với nhiều phong cách nội thất khác nhau. \n\nBàn ăn phù hợp với gia đình từ 6-8 người, là nơi lý tưởng để cả gia đình sum vầy trong những bữa cơm ấm cúng. Mặt bàn được phủ lớp sơn chống thấm, chống trầy xước, giúp bảo vệ bề mặt gỗ và dễ dàng lau chùi. Ghế được làm từ khung gỗ chắc chắn, đảm bảo độ bền và tuổi thọ cao. \n\nBộ bàn ăn gỗ sồi chân X 6 ghế màu óc chó không chỉ là một sản phẩm nội thất mà còn là điểm nhấn quan trọng, thể hiện gu thẩm mỹ và phong cách sống của gia chủ. Sản phẩm phù hợp với nhiều phong cách nội thất khác nhau như: hiện đại, tối giản, Bắc Âu (Scandinavian) hoặc tân cổ điển.  Mang đến sự tiện nghi và sang trọng cho không gian sống của bạn, đồng thời tạo sự thoải mái và gắn kết cho các thành viên trong gia đình. Sở hữu bộ bàn ăn này, bạn không chỉ có một nơi dùng bữa lý tưởng mà còn là một tác phẩm nghệ thuật trang trí cho ngôi nhà của mình.',2,'https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Mơi /z4752667390322_55b65683800adf005a625e53c11a43dc-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Mơi /z4752667390322_55b65683800adf005a625e53c11a43dc-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Mơi /z4752667344918_919eb7cc1a54569c2e5fa484d00c9598-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Mơi /z4752667325965_85e33c387c5b266d05fef0113f1ddc27-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Mơi /z4752667320789_7462323bf02bae57d5372985004b134d-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Mơi /z4730847009193_6bc2937681b5a8716830b321c2d558b8-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Mơi /z4711730920262_39b0dd2080d1ced96f5d6e2a6813afba-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Mơi /z4711730918349_3d2bcc4ff41adb1c277e3412b222f1af-500x500.jpg',9950000.00,1,'2025-07-08 20:33:53.022251','2025-07-08 20:33:53.022251'),(12,'Bàn Ăn Gỗ Sồi Hiện Đại Chân Hươu Mặt Khuân Đá 4 ghế','Bàn ăn gỗ sồi hiện đại chân hươu mặt khuân đá kết hợp vẻ đẹp tự nhiên của gỗ sồi và sự sang trọng của mặt đá, mang đến không gian ăn uống ấm cúng và tinh tế. Thiết kế chân hươu độc đáo không chỉ tạo điểm nhấn thẩm mỹ mà còn đảm bảo sự vững chắc và ổn định cho bàn. Mặt bàn được chế tác từ đá khuân, nổi bật với đường vân tự nhiên, chống thấm và dễ dàng vệ sinh. Bốn ghế đi kèm được thiết kế đồng bộ, mang đến sự hài hòa và thoải mái cho người sử dụng. Công nghệ sơn PU cao cấp giúp bảo vệ bề mặt gỗ, chống trầy xước và giữ màu sắc bền đẹp theo thời gian.\n\nBàn ăn này không chỉ là nơi thưởng thức những bữa ăn ngon mà còn là trung tâm kết nối các thành viên trong gia đình. Kích thước bàn phù hợp với nhiều không gian phòng ăn, từ căn hộ chung cư đến nhà phố. Phong cách hiện đại của bàn ăn dễ dàng kết hợp với nhiều phong cách nội thất khác nhau, từ tối giản đến Scandinavian.\n\nSản phẩm mang đến sự tiện nghi, thoải mái và vẻ đẹp sang trọng cho không gian sống của bạn. Chất liệu cao cấp đảm bảo độ bền và tuổi thọ của sản phẩm. Mặt đá khuân giúp bạn dễ dàng lau chùi sau mỗi bữa ăn, tiết kiệm thời gian và công sức. Thiết kế chân hươu độc đáo tạo nên sự khác biệt và thu hút mọi ánh nhìn. Với bàn ăn gỗ sồi hiện đại chân hươu mặt khuân đá, bạn sẽ có những khoảnh khắc đáng nhớ bên gia đình và bạn bè.',2,'https://goxinh.com.vn/image/cache/Ban-ghe-an/z3270798591705_e748e625bfdfe374074bc1a7f33163a8-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Giao Khách/z4147002405649_108d5e47ab073bcf55fba11422324113-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Giao Khách/z4147002425289_81cac29fac3d182ff601ca7022e91f1b-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Gỗ Sồi 4 ghế/z5420557509778_7d71280c22466bbffff93b772c199beb-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Gỗ Sồi 4 ghế/z5420557438810_7304bba12c8e460c8467370eed6086e6-500x500.jpg',6300000.00,1,'2025-07-08 20:33:53.023431','2025-07-08 20:33:53.023431'),(13,'Bàn Ăn Gỗ Sồi Hiện Đại Chân Đũa Mặt Gỗ 6 Ghế','Bàn ăn gỗ sồi hiện đại chân đũa mặt gỗ 6 ghế là sự kết hợp hoàn hảo giữa vẻ đẹp tự nhiên của gỗ sồi và phong cách thiết kế tối giản, tinh tế. Mặt bàn được làm từ gỗ sồi tự nhiên nguyên khối hoặc ghép thanh, nổi bật với những đường vân gỗ độc đáo và màu sắc ấm áp. Chân bàn được thiết kế theo kiểu dáng chân đũa thanh mảnh, tạo cảm giác nhẹ nhàng, thoáng đãng cho không gian bếp hoặc phòng ăn. \n\nSản phẩm được chế tác tỉ mỉ, đảm bảo độ bền cao và khả năng chịu lực tốt. Bề mặt gỗ được xử lý kỹ lưỡng, chống thấm nước và dễ dàng vệ sinh. Thiết kế 6 ghế ngồi rộng rãi, phù hợp cho các bữa ăn gia đình hoặc những buổi tụ họp bạn bè. \n\nBàn ăn gỗ sồi chân đũa không chỉ là một món đồ nội thất hữu dụng mà còn là điểm nhấn thẩm mỹ cho không gian sống. Sản phẩm phù hợp với nhiều phong cách nội thất khác nhau, từ hiện đại, tối giản đến Bắc Âu (Scandinavian). \n\nSử dụng bàn ăn gỗ sồi giúp mang đến sự ấm cúng, gần gũi và thoải mái cho mỗi bữa ăn. Góp phần tạo nên không gian sum họp hạnh phúc và gắn kết cho gia đình.',2,'https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Mơi /z5330267833651_35fa98e8f41ebcd0ec92b35aa9f1cfa0-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Mơi /z5330267833651_35fa98e8f41ebcd0ec92b35aa9f1cfa0-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Mơi /z5330267826388_a6aa2ce2127058fad35adafebfeabd53-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Mơi /z5330267833772_1cc26ef158374d34a1c66936114204a1-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Mơi /z5330267878610_8a51cbdfa0e947c8a7978165d755e82a-500x500.jpg',8600000.00,1,'2025-07-08 20:33:53.024678','2025-07-08 20:33:53.024678'),(14,'Bàn Ăn Gỗ Sồi Hiện Đại Chân Đũa Mặt Đá Trắng 6 Ghế','Bàn ăn gỗ sồi hiện đại chân đũa mặt đá trắng 6 ghế là sự kết hợp tinh tế giữa vẻ đẹp tự nhiên và phong cách tối giản. Thiết kế chân đũa thanh thoát tạo cảm giác nhẹ nhàng, thoáng đãng cho không gian bếp hoặc phòng ăn. Mặt bàn đá trắng mang đến vẻ sang trọng, hiện đại, đồng thời dễ dàng vệ sinh và chống thấm tốt. Bộ bàn ăn này không chỉ là nơi sum họp gia đình trong mỗi bữa cơm mà còn là điểm nhấn thẩm mỹ độc đáo, thể hiện gu cá tính của gia chủ.\n\nKhung bàn được chế tác từ gỗ sồi tự nhiên, trải qua quy trình tẩm sấy kỹ lưỡng, đảm bảo độ bền bỉ và khả năng chống mối mọt. Bề mặt gỗ được hoàn thiện tỉ mỉ, giữ nguyên vân gỗ tự nhiên, mang đến cảm giác ấm cúng và gần gũi. Mặt đá trắng được lựa chọn từ những phiến đá cao cấp, có độ bóng mịn và vân đá độc đáo, tạo nên sự khác biệt cho sản phẩm.\n\nVới kích thước rộng rãi, bộ bàn ăn này thoải mái đáp ứng nhu cầu sử dụng của gia đình 6 người. Mặt bàn đá có khả năng chịu nhiệt tốt, dễ dàng lau chùi các vết bẩn do thức ăn hoặc đồ uống gây ra. Phong cách hiện đại của bộ bàn ăn dễ dàng hòa hợp với nhiều không gian nội thất khác nhau, từ căn hộ chung cư đến nhà phố, biệt thự. Sản phẩm mang đến trải nghiệm ăn uống thoải mái, tiện nghi và nâng tầm phong cách sống cho gia đình bạn.',2,'https://goxinh.com.vn/image/cache/Ban-ghe-an/2fa1e32cd4371b694226-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/2fa1e32cd4371b694226-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Mơi /z5420557449666_b27e5019fe2ec88bec3228352f718485-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Mơi /z5330267833651_35fa98e8f41ebcd0ec92b35aa9f1cfa0-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Mơi /z3314922156481_9044b8f6f2c18d0296089a542af26b06-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Mơi /z5330267826388_a6aa2ce2127058fad35adafebfeabd53-500x500.jpg',8600000.00,1,'2025-07-08 20:33:53.027619','2025-07-08 20:33:53.027619'),(15,'Bàn Ăn Gỗ Sồi Hiện Đại Mặt Đá Chân U 6 Ghế màu óc chó','Bàn ăn gỗ sồi hiện đại mặt đá chân U là sự kết hợp hoàn hảo giữa vẻ đẹp tự nhiên và phong cách thiết kế tối giản, sang trọng. Mặt bàn đá cao cấp với vân đá độc đáo, tạo điểm nhấn ấn tượng cho không gian bếp hoặc phòng ăn. Chân bàn hình chữ U được làm từ gỗ sồi tự nhiên, đảm bảo độ vững chắc và bền bỉ. 6 ghế ăn màu óc chó với thiết kế thanh lịch, đường nét tinh tế, mang đến sự thoải mái và ấm cúng cho mỗi bữa ăn gia đình. \n\nThiết kế chân chữ U không chỉ tạo sự khác biệt mà còn mang lại không gian thoáng đãng dưới gầm bàn, giúp người ngồi cảm thấy thoải mái hơn. Mặt đá có khả năng chống thấm, chống trầy xước và dễ dàng vệ sinh, đảm bảo bàn ăn luôn giữ được vẻ đẹp như mới. Gỗ sồi tự nhiên được xử lý kỹ lưỡng, chống mối mọt và cong vênh, mang lại độ bền vượt trội cho sản phẩm. Màu sắc óc chó của ghế tạo nên sự tương phản hài hòa, làm tăng thêm vẻ đẹp hiện đại và sang trọng cho bộ bàn ăn.\n\nBộ bàn ăn này phù hợp với nhiều phong cách nội thất khác nhau, từ hiện đại, tối giản đến phong cách Scandinavian. Với kích thước rộng rãi, bàn ăn có thể đáp ứng nhu cầu sử dụng của gia đình từ 6-8 người, là nơi lý tưởng để sum họp, chia sẻ những khoảnh khắc ấm cúng bên nhau. Sở hữu bộ bàn ăn gỗ sồi mặt đá chân U 6 ghế màu óc chó, bạn không chỉ có một sản phẩm nội thất chất lượng mà còn góp phần nâng tầm không gian sống của gia đình.',2,'https://goxinh.com.vn/image/cache/Ban-ghe-an/Giao Khách/z4785771197126_5ad321bf75592bc8c2209b0393ef2d64-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/z3402693723289_f27939a24b3d373a6bb805e83ecb2ed8-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Giao Khách/z4785771197126_5ad321bf75592bc8c2209b0393ef2d64-500x500.jpg',8990000.00,1,'2025-07-08 20:33:53.031332','2025-07-08 20:33:53.031332'),(16,'Bàn ăn Gỗ Sồi Tròn  6 ghế','Bàn ăn Gỗ Sồi Tròn 6 ghế là sự kết hợp hoàn hảo giữa vẻ đẹp tự nhiên, sự sang trọng và tính tiện dụng, mang đến không gian ấm cúng và thân thiện cho mỗi bữa ăn gia đình. Thiết kế mặt bàn tròn tinh tế tạo cảm giác gần gũi, giúp mọi người dễ dàng giao tiếp và chia sẻ. Chân bàn được thiết kế vững chắc, với các đường nét uốn lượn mềm mại hoặc dáng trụ thẳng đứng hiện đại, tùy thuộc vào phiên bản, tạo điểm nhấn thẩm mỹ cho tổng thể sản phẩm. \n\nBàn được chế tác từ gỗ sồi tự nhiên, trải qua quy trình tẩm sấy kỹ lưỡng để đảm bảo độ bền, chống mối mọt và cong vênh. Bề mặt gỗ được xử lý tỉ mỉ, phủ lớp sơn PU cao cấp, vừa bảo vệ gỗ, vừa tôn lên vẻ đẹp vân gỗ tự nhiên, mang đến cảm giác ấm áp và sang trọng. Công nghệ sơn hiện đại giúp bàn có khả năng chống trầy xước, dễ dàng vệ sinh và lau chùi. \n\nBàn ăn Gỗ Sồi Tròn 6 ghế không chỉ là nơi để thưởng thức những bữa ăn ngon, mà còn là nơi gia đình sum vầy, chia sẻ những khoảnh khắc ý nghĩa. Với kích thước phù hợp, bàn có thể đặt ở nhiều không gian khác nhau, từ phòng bếp, phòng ăn gia đình đến các căn hộ chung cư. Phong cách thiết kế đơn giản nhưng tinh tế giúp bàn dễ dàng phối hợp với nhiều phong cách nội thất khác nhau, từ phong cách hiện đại, tối giản đến phong cách Bắc Âu (Scandinavian) hay phong cách đồng quê. \n\nSản phẩm mang đến sự thoải mái và tiện nghi cho người sử dụng. Mặt bàn rộng rãi, đủ chỗ cho 6 người ngồi thoải mái. Thiết kế tròn giúp mọi người dễ dàng tiếp cận thức ăn và đồ uống. Với chất liệu gỗ sồi bền đẹp, bàn ăn Gỗ Sồi Tròn 6 ghế sẽ là một khoản đầu tư xứng đáng cho gia đình bạn, đồng hành cùng bạn trong nhiều năm tới, tạo nên những kỷ niệm đáng nhớ trong mỗi bữa ăn.',2,'https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Tròn Gỗ Sồi/464576501_1331355698073490_8960619002359530759_n-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Tròn Gỗ Sồi/464511507_1331355738073486_1919753899073044050_n-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Tròn Gỗ Sồi/464576501_1331355698073490_8960619002359530759_n-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Tròn Gỗ Sồi/464585451_1331355654740161_1300847641558541508_n-500x500.jpg',8600000.00,1,'2025-07-08 20:33:53.032518','2025-07-08 20:33:53.032518'),(17,'Bàn Ăn Thông Minh Gấp Gọn Gỗ Sồi','Bàn ăn thông minh gấp gọn gỗ sồi là giải pháp hoàn hảo cho không gian sống hiện đại, đặc biệt là những căn hộ có diện tích hạn chế. Thiết kế tối giản, thanh lịch với những đường nét vuông vắn, tinh tế, bàn ăn này dễ dàng hòa nhập vào nhiều phong cách nội thất khác nhau, từ Scandinavian ấm cúng đến Minimalist hiện đại. Điểm nhấn của sản phẩm nằm ở khả năng gấp gọn linh hoạt, biến một chiếc bàn ăn rộng rãi phục vụ cho cả gia đình thành một chiếc bàn console nhỏ gọn khi không sử dụng, giúp tiết kiệm không gian tối đa. \n\nBàn ăn được chế tác từ gỗ sồi tự nhiên, nổi tiếng với độ bền cao, khả năng chống mối mọt tốt và vân gỗ đẹp mắt. Bề mặt gỗ được xử lý tỉ mỉ, phủ lớp sơn PU cao cấp, vừa tăng tính thẩm mỹ, vừa bảo vệ gỗ khỏi trầy xước và dễ dàng vệ sinh. Cơ chế gấp gọn thông minh được thiết kế chắc chắn, đảm bảo an toàn và dễ dàng thao tác. \n\nKhi mở rộng, bàn ăn có thể phục vụ thoải mái cho 4-6 người. Khi gấp gọn, bàn biến thành một chiếc kệ trang trí tiện dụng, có thể đặt ở hành lang, phòng khách hoặc phòng bếp. Sản phẩm phù hợp với những căn hộ chung cư, nhà phố có diện tích nhỏ, hoặc những gia đình yêu thích sự tiện nghi và đa năng. Với bàn ăn thông minh gấp gọn gỗ sồi, bạn sẽ không còn phải lo lắng về vấn đề diện tích khi muốn tổ chức những bữa ăn ấm cúng bên gia đình và bạn bè.\n\nSở hữu bàn ăn thông minh gấp gọn gỗ sồi, bạn không chỉ có một món đồ nội thất tiện dụng mà còn là một điểm nhấn tinh tế cho không gian sống của mình. Sản phẩm là sự kết hợp hoàn hảo giữa tính thẩm mỹ, công năng và độ bền, mang đến trải nghiệm sử dụng tuyệt vời cho người dùng.',2,'https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Ăn Thông Minh /z4966436906036_0b0c8dcd1a4d573f1dc320dcda93cea2-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Ăn Thông Minh /z4966436906036_0b0c8dcd1a4d573f1dc320dcda93cea2-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Ăn Thông Minh /z5955537438497_09095a83f7cff7aadd6c1a42a5598a36-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Ăn Thông Minh /z5740381923975_72d0298b4e7b12eacda2f6ed4cb1ded9-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Ăn Thông Minh /241050873_3060337464251659_2619091312112653884_n-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Ăn Thông Minh /z3495467348916_217cd29df6558d765fb062274d13d5e2-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Ăn Thông Minh /z3495467362324_954859765d4100e50aefcb71d3196c28-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Ăn Thông Minh /z3495467364374_82aa215d02a0ae27e982cc42357d8597-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Ăn Thông Minh /z4966436892731_c63a8ee42982e545feabaf01d659375d-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Ăn Thông Minh /z4966436898461_d2ec48c94db3b32e68cd2af76a9e2984-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Ăn Thông Minh /z5740381949119_b30d6e8a53bc9358088d93d8f9e46026-500x500.jpg',3950000.00,1,'2025-07-08 20:33:53.033637','2025-07-08 20:33:53.033637'),(18,'Bàn ăn xoan đào Bầu Dục 1m6 6 ghế','Bàn ăn xoan đào Bầu Dục 1m6 6 ghế là sự kết hợp hoàn hảo giữa vẻ đẹp truyền thống và sự tiện nghi hiện đại, mang đến không gian ấm cúng và sang trọng cho phòng bếp hoặc phòng ăn của bạn. Thiết kế mặt bàn hình bầu dục mềm mại, không góc cạnh, tạo cảm giác thân thiện và dễ chịu, đồng thời tối ưu hóa không gian sử dụng, giúp các thành viên trong gia đình dễ dàng tương tác với nhau trong bữa ăn. Chân bàn được thiết kế vững chắc, với những đường cong tinh tế, tạo nên sự cân đối và hài hòa cho tổng thể sản phẩm. \n\nBàn ăn được chế tác từ gỗ xoan đào tự nhiên, trải qua quy trình tẩm sấy kỹ lưỡng, đảm bảo độ bền cao, chống mối mọt, cong vênh và chịu được tác động của thời tiết. Bề mặt gỗ được phủ lớp sơn PU cao cấp, bóng mịn, giúp bảo vệ gỗ khỏi trầy xước, dễ dàng vệ sinh và tăng tính thẩm mỹ cho sản phẩm. Ghế ăn được thiết kế với lưng tựa cong nhẹ, ôm sát cơ thể, mang lại cảm giác thoải mái khi ngồi. Mặt ghế được bọc da simili hoặc nỉ cao cấp, êm ái và dễ chịu. \n\nBộ bàn ăn xoan đào Bầu Dục 1m6 6 ghế không chỉ là nơi để gia đình sum vầy bên những bữa cơm ngon mà còn là điểm nhấn ấn tượng, thể hiện gu thẩm mỹ tinh tế của gia chủ. Sản phẩm phù hợp với nhiều phong cách nội thất khác nhau, từ cổ điển, tân cổ điển đến hiện đại, mang đến sự sang trọng và đẳng cấp cho không gian sống của bạn. Với kích thước 1m6, bộ bàn ăn phù hợp với những gia đình có từ 4-6 thành viên, tạo không gian thoải mái và rộng rãi cho mọi người.\n\nLợi ích cho người dùng: Mang đến không gian ăn uống ấm cúng, sang trọng và tiện nghi. Độ bền cao, dễ dàng vệ sinh và bảo quản. Thể hiện gu thẩm mỹ tinh tế và đẳng cấp của gia chủ. Tạo sự gắn kết và sum vầy cho các thành viên trong gia đình.',2,'https://goxinh.com.vn/image/cache/Ban-ghe-an/271734790_112690381292052_8905056407984264444_n-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Ăn XOan Đào/Bàn Bầu dục/IMG_6803-copy-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Ăn XOan Đào/Bàn Bầu dục/IMG_6805-copy-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Ăn XOan Đào/Bàn Bầu dục/IMG_6807-copy-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Ăn XOan Đào/Bàn Bầu dục/IMG_6808-copy-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Ăn XOan Đào/Bàn Bầu dục/IMG_6815-copy-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-ghe-an/Bàn Ăn XOan Đào/Bàn Bầu dục/IMG_6823-copy-500x500.jpg',4990000.00,1,'2025-07-08 20:33:53.034779','2025-07-08 20:33:53.034779'),(19,'Bàn Ghế Sofa gỗ sồi  Góc đùi gà','Bộ sofa gỗ sồi góc đùi gà là sự kết hợp hoàn hảo giữa nét đẹp truyền thống và phong cách hiện đại, mang đến không gian phòng khách sự ấm cúng, sang trọng và tiện nghi. Thiết kế góc đùi gà độc đáo tạo điểm nhấn ấn tượng, đồng thời tối ưu hóa không gian sử dụng, phù hợp với nhiều kiểu kiến trúc khác nhau. Khung sofa được chế tác từ gỗ sồi tự nhiên, trải qua quy trình tẩm sấy kỹ lưỡng, đảm bảo độ bền chắc, chống mối mọt và cong vênh. Bề mặt gỗ được xử lý tỉ mỉ, sơn phủ PU cao cấp, làm nổi bật vẻ đẹp vân gỗ tự nhiên và tăng khả năng chống trầy xước. Nệm ngồi và tựa lưng được bọc vải hoặc da cao cấp, êm ái và thoáng mát, mang lại cảm giác thoải mái tối đa cho người sử dụng. Thiết kế tay vịn rộng rãi, tạo sự thoải mái khi thư giãn hoặc đọc sách. Sofa góc đùi gà không chỉ là nơi tiếp khách trang trọng mà còn là không gian lý tưởng để cả gia đình quây quần, trò chuyện và tận hưởng những phút giây thư giãn bên nhau. Sản phẩm phù hợp với nhiều phong cách nội thất khác nhau, từ cổ điển, tân cổ điển đến hiện đại, tối giản. Với bộ sofa gỗ sồi góc đùi gà, bạn sẽ sở hữu một món đồ nội thất đẳng cấp, bền đẹp theo thời gian, góp phần nâng tầm không gian sống và thể hiện gu thẩm mỹ tinh tế.',5,'https://goxinh.com.vn/image/cache/Sofa /gdg1-500x500.jpg;https://goxinh.com.vn/image/cache/Sofa /gdg2-500x500.jpg',16500000.00,1,'2025-07-08 20:33:53.036119','2025-07-08 20:33:53.036119'),(20,'Bàn Ghế Sofa Gỗ Sồi Hai Văng Chân Quỳ','Bộ bàn ghế sofa gỗ sồi hai văng chân quỳ là sự kết hợp hài hòa giữa vẻ đẹp truyền thống và phong cách hiện đại, mang đến không gian phòng khách sự sang trọng, ấm cúng và gần gũi với thiên nhiên. Thiết kế chân quỳ vững chãi, chạm khắc tinh xảo, thể hiện sự tỉ mỉ trong từng đường nét, đồng thời tạo điểm nhấn độc đáo cho sản phẩm. Hai văng sofa được thiết kế rộng rãi, thoải mái, phù hợp cho gia đình hoặc nhóm bạn bè cùng nhau trò chuyện, thư giãn. Phần tựa lưng và tay vịn được bọc đệm êm ái, mang lại cảm giác dễ chịu khi sử dụng. \n\nSản phẩm được chế tác từ gỗ sồi tự nhiên, trải qua quy trình tẩm sấy kỹ lưỡng, đảm bảo độ bền cao, khả năng chống mối mọt và cong vênh. Bề mặt gỗ được xử lý và sơn phủ bằng công nghệ hiện đại, vừa bảo vệ gỗ khỏi tác động của môi trường, vừa tôn lên vẻ đẹp tự nhiên của vân gỗ. \n\nBộ sofa gỗ sồi hai văng chân quỳ không chỉ là món đồ nội thất, mà còn là điểm nhấn thể hiện gu thẩm mỹ tinh tế của gia chủ. Sản phẩm phù hợp với nhiều phong cách nội thất khác nhau, từ cổ điển đến hiện đại, từ tối giản đến sang trọng. Với kích thước vừa phải, bộ sofa phù hợp với nhiều không gian phòng khách, từ căn hộ chung cư đến nhà phố, biệt thự. Lựa chọn bộ sofa gỗ sồi hai văng chân quỳ là bạn đang đầu tư vào sự thoải mái, tiện nghi và vẻ đẹp lâu bền cho không gian sống của mình.',5,'https://goxinh.com.vn/image/cache/Sofa /z3340716772452_a87d3d3d3014f7cdd014a24d8a83e6f4-500x500.jpg;https://goxinh.com.vn/image/cache/Sofa /z3340716772452_a87d3d3d3014f7cdd014a24d8a83e6f4-500x500.jpg;https://goxinh.com.vn/image/cache/Sofa /z3340716807670_83e5d327235b4326837d7662328371f0-500x500.jpg',18999000.00,1,'2025-07-08 20:33:53.039383','2025-07-08 20:33:53.039383'),(21,'Bàn Ghế Sofa Gỗ Sồi Hai Văng Chân Đùi Gà','Bộ bàn ghế sofa gỗ sồi hai văng chân đùi gà mang đến sự kết hợp hoàn hảo giữa vẻ đẹp truyền thống và sự tiện nghi hiện đại cho không gian phòng khách của bạn. Thiết kế chân đùi gà uốn cong mềm mại, tạo điểm nhấn ấn tượng và độc đáo, đồng thời tăng thêm sự vững chãi cho sản phẩm. Khung sofa được làm từ gỗ sồi tự nhiên chọn lọc, đảm bảo độ bền bỉ, khả năng chịu lực tốt và chống mối mọt. Các chi tiết chạm khắc tinh xảo, tỉ mỉ trên tựa lưng và tay vịn thể hiện sự tinh tế trong từng đường nét. \n\nSofa được thiết kế với hai văng đối xứng, tạo không gian trò chuyện ấm cúng và gần gũi cho gia đình và bạn bè. Đệm ngồi và tựa lưng được bọc vải nỉ cao cấp, êm ái và thoáng khí, mang lại cảm giác thoải mái tối đa khi sử dụng. Màu sắc trang nhã, dễ dàng phối hợp với nhiều phong cách nội thất khác nhau, từ cổ điển, tân cổ điển đến hiện đại. \n\nBộ sofa này không chỉ là một món đồ nội thất, mà còn là một tác phẩm nghệ thuật, góp phần nâng tầm không gian sống của bạn. Với kích thước vừa phải, sofa phù hợp với nhiều diện tích phòng khách, từ chung cư đến nhà phố. Đặc biệt, gỗ sồi tự nhiên mang lại cảm giác ấm áp và gần gũi với thiên nhiên, tạo nên một không gian sống thư giãn và thoải mái. Sở hữu bộ sofa gỗ sồi hai văng chân đùi gà, bạn sẽ có một không gian phòng khách sang trọng, tiện nghi và đầy phong cách.',5,'https://goxinh.com.vn/image/cache/Sofa /2-500x500.jpg;https://goxinh.com.vn/image/cache/Sofa /z3340716772452_a87d3d3d3014f7cdd014a24d8a83e6f4-500x500.jpg;https://goxinh.com.vn/image/cache/Sofa /2-500x500.jpg',19999000.00,1,'2025-07-08 20:33:53.040658','2025-07-08 20:33:53.040658'),(22,'Bàn ghế sofa gỗ sồi hai văng thuyền','Bộ bàn ghế sofa gỗ sồi hai văng thuyền mang đến vẻ đẹp sang trọng, ấm cúng và đậm chất truyền thống cho không gian phòng khách. Thiết kế văng thuyền độc đáo với những đường cong mềm mại, uyển chuyển tạo điểm nhấn khác biệt, thu hút mọi ánh nhìn. \n\nKhung ghế được chế tác từ gỗ sồi tự nhiên, trải qua quy trình tẩm sấy kỹ lưỡng, đảm bảo độ bền bỉ, chống mối mọt và cong vênh trong quá trình sử dụng. Bề mặt gỗ được hoàn thiện tỉ mỉ, giữ nguyên vẻ đẹp tự nhiên của vân gỗ, đồng thời phủ lớp sơn PU cao cấp, bảo vệ gỗ khỏi tác động của môi trường và dễ dàng vệ sinh. \n\nĐệm ngồi và tựa lưng được bọc vải nỉ hoặc da cao cấp (tùy chọn), mang đến cảm giác êm ái, thoải mái khi sử dụng. Lớp đệm mút dày dặn, có độ đàn hồi tốt, giúp nâng đỡ cơ thể, giảm thiểu tình trạng đau lưng, mỏi vai gáy. \n\nBộ sofa này không chỉ là nơi để tiếp khách, thư giãn mà còn là một tác phẩm nghệ thuật, góp phần tô điểm cho không gian sống thêm phần tinh tế và đẳng cấp. Với kích thước vừa phải, bộ sofa phù hợp với nhiều không gian phòng khách khác nhau, từ căn hộ chung cư đến nhà phố, biệt thự. Phong cách thiết kế mang hơi hướng cổ điển kết hợp hiện đại, dễ dàng hòa nhập với nhiều phong cách nội thất khác nhau, như phong cách Indochine, phong cách Rustic, phong cách Scandinavian. \n\nSở hữu bộ bàn ghế sofa gỗ sồi hai văng thuyền, bạn sẽ có một không gian sống tiện nghi, thoải mái và đầy tính thẩm mỹ, nơi bạn có thể tận hưởng những giây phút thư giãn bên gia đình và bạn bè.',5,'https://goxinh.com.vn/image/cache/Sofa /bàn thuyền-500x500.jpg;https://goxinh.com.vn/image/cache/Sofa /z3945634110289_bf9be5da7b5c670e9c95ed4d1b8506d2-500x500.jpg;https://goxinh.com.vn/image/cache/Sofa /bàn thuyền-500x500.jpg',19999000.00,1,'2025-07-08 20:33:53.041820','2025-07-08 20:33:53.041820'),(23,'Bàn Trà Sofa Mặt Đá Dài Khung Kim Cương 1m2','Bàn trà sofa mặt đá dài khung kim cương 1m2 là sự kết hợp hoàn hảo giữa vẻ đẹp hiện đại và sự tiện dụng, mang đến điểm nhấn sang trọng cho không gian phòng khách của bạn. Thiết kế khung kim cương độc đáo, được chế tác tỉ mỉ, tạo nên sự vững chắc và vẻ đẹp tinh tế. Mặt bàn đá tự nhiên hoặc nhân tạo cao cấp không chỉ bền bỉ, dễ dàng vệ sinh mà còn tôn lên vẻ đẹp đẳng cấp của sản phẩm. Bề mặt đá với vân đá độc đáo tạo nên sự khác biệt cho mỗi sản phẩm. \n\nBàn trà có kích thước 1m2, đủ rộng rãi để bạn thoải mái bày biện đồ uống, sách báo hay vật dụng trang trí. Chiều cao bàn được thiết kế phù hợp với chiều cao ghế sofa thông thường, mang lại sự thoải mái khi sử dụng. Khung chân kim loại sơn tĩnh điện đảm bảo độ bền, chống gỉ sét và dễ dàng di chuyển. \n\nSản phẩm phù hợp với nhiều phong cách nội thất khác nhau, từ hiện đại, tối giản đến tân cổ điển. Bàn trà sofa mặt đá dài khung kim cương không chỉ là một vật dụng nội thất hữu ích mà còn là một tác phẩm nghệ thuật, thể hiện gu thẩm mỹ tinh tế của gia chủ. Lựa chọn sản phẩm này, bạn không chỉ sở hữu một chiếc bàn trà đẹp mà còn nâng tầm không gian sống của mình.',5,'https://goxinh.com.vn/image/cache/Bàn Trà/z3848262781481_5fc107f0d48c2b4cbdf7719c235d6e46-500x500.jpg;https://goxinh.com.vn/image/cache/Bàn Trà/z3848262729715_2ab7fea0c5dc50605021159be26946d8-500x500.jpg;https://goxinh.com.vn/image/cache/Bàn Trà/z3848262781481_5fc107f0d48c2b4cbdf7719c235d6e46-500x500.jpg',1899000.00,1,'2025-07-08 20:33:53.042902','2025-07-08 20:33:53.042902'),(24,'Bàn Trà Sofa Tròn 70cm','Sản phẩm Bàn Trà Sofa Tròn 70cm với thiết kế hiện đại, chất lượng cao. Phù hợp cho không gian nội thất gia đình. Chất liệu bền bỉ, dễ sử dụng và bảo quản. Mang lại sự tiện nghi và thẩm mỹ cho ngôi nhà của bạn. Sản phẩm được gia công tỉ mỉ với công nghệ tiên tiến, đảm bảo độ bền và an toàn khi sử dụng. Thiết kế tinh tế, phù hợp với nhiều phong cách nội thất khác nhau từ hiện đại đến cổ điển.',5,'https://goxinh.com.vn/image/cache/Bàn Trà/z3848262940754_75f828dff060c36076cedf79f8f9e7b3-500x500.jpg;https://goxinh.com.vn/image/cache/Bàn Trà/z3848262940754_75f828dff060c36076cedf79f8f9e7b3-500x500.jpg',1499000.00,1,'2025-07-08 20:33:53.044024','2025-07-08 20:33:53.044024'),(25,'Bàn Trà Sofa Đôi Mặt Đá','Bàn trà sofa đôi mặt đá là sự kết hợp hoàn hảo giữa vẻ đẹp hiện đại và công năng sử dụng tối ưu, mang đến điểm nhấn sang trọng cho không gian phòng khách của bạn. Thiết kế bàn trà tập trung vào sự tối giản, tinh tế với mặt đá tự nhiên hoặc đá nhân tạo cao cấp, vân đá độc đáo tạo nên vẻ đẹp riêng biệt cho từng sản phẩm. Khung bàn được chế tác tỉ mỉ từ gỗ tự nhiên hoặc kim loại sơn tĩnh điện, đảm bảo độ bền và khả năng chịu lực cao. Bàn có cấu trúc đôi, gồm hai bàn nhỏ ghép lại hoặc một bàn lớn kết hợp với bàn nhỏ hơn, tạo sự linh hoạt trong sử dụng và bày trí. \n\nĐiểm nổi bật của bàn trà sofa đôi mặt đá là tính tiện dụng. Bạn có thể sử dụng bàn lớn để tiếp khách, đặt đồ ăn, thức uống, trong khi bàn nhỏ hơn có thể dùng để đặt sách báo, điều khiển tivi hoặc trang trí. Thiết kế này đặc biệt phù hợp với các không gian phòng khách vừa và lớn, nơi gia chủ muốn tạo sự thoải mái và tiện nghi. Bề mặt đá dễ dàng vệ sinh, chống thấm nước, giúp bạn luôn giữ được vẻ đẹp của bàn trà. \n\nBàn trà sofa đôi mặt đá phù hợp với nhiều phong cách nội thất khác nhau, từ hiện đại, tối giản đến Scandinavian, tân cổ điển. Sản phẩm không chỉ là một món đồ nội thất hữu dụng mà còn là một tác phẩm nghệ thuật, góp phần nâng tầm không gian sống của bạn. Lựa chọn bàn trà sofa đôi mặt đá là sự đầu tư thông minh cho không gian sống sang trọng và tiện nghi.',5,'https://goxinh.com.vn/image/cache/Bàn Trà/z3848262707920_39c2d8537be13b878af1399f4c487342-500x500.jpg;https://goxinh.com.vn/image/cache/Bàn Trà/Ban-Tra-Doi-Mat-Da-Sofa-510x510-500x500.jpg;https://goxinh.com.vn/image/cache/Bàn Trà/z3848262707920_39c2d8537be13b878af1399f4c487342-500x500.jpg',1799000.00,1,'2025-07-08 20:33:53.045202','2025-07-08 20:33:53.045202'),(26,'Bộ Ghế Sofa Góc Bọc Nỉ Cao Cấp  - SF01 - 2m8 x180cm','Bộ ghế sofa góc bọc nỉ cao cấp SF01 là sự kết hợp hoàn hảo giữa thiết kế hiện đại, sự thoải mái và độ bền vượt trội. Với kích thước 2m8 x 1m8, bộ sofa này phù hợp với nhiều không gian phòng khách, từ căn hộ chung cư đến nhà phố. Kiểu dáng góc chữ L giúp tối ưu hóa diện tích, tạo ra không gian quây quần ấm cúng cho gia đình và bạn bè. Phần tựa lưng và tay vịn được thiết kế với độ nghiêng vừa phải, mang lại cảm giác thư giãn tối đa khi ngồi hoặc nằm. Chất liệu nỉ cao cấp được tuyển chọn kỹ lưỡng, không chỉ mềm mại, êm ái mà còn có khả năng chống bám bụi và dễ dàng vệ sinh. Khung ghế được làm từ gỗ tự nhiên đã qua xử lý chống mối mọt, đảm bảo độ bền và tuổi thọ lâu dài. Đệm mút cao cấp có độ đàn hồi tốt, không bị xẹp lún sau thời gian dài sử dụng. Màu sắc trung tính của bộ sofa dễ dàng phối hợp với nhiều phong cách nội thất khác nhau, từ hiện đại, tối giản đến Scandinavian. Bộ sofa góc SF01 không chỉ là nơi để bạn nghỉ ngơi, thư giãn mà còn là điểm nhấn sang trọng, tinh tế cho không gian sống của bạn. Lựa chọn bộ sofa góc SF01 là lựa chọn cho sự thoải mái, tiện nghi và phong cách.',5,'https://goxinh.com.vn/image/cache/Sofa /z3845367880386_a212bf4ba35582b34bd020efdb7720fd-500x500.jpg;https://goxinh.com.vn/image/cache/Sofa /z3845367864277_d72d31175630c8de276641f7b165f4d6-500x500.jpg;https://goxinh.com.vn/image/cache/Sofa /z3845368072659_5605cd0d3ffbd467d00e2b3bb474e237-500x500.jpg',7800000.00,1,'2025-07-08 20:33:53.046274','2025-07-08 20:33:53.046274'),(27,'Kệ tivi Aris 1m4','Kệ tivi Aris 1m4 là sự kết hợp hoàn hảo giữa phong cách hiện đại và tính ứng dụng cao, mang đến giải pháp lưu trữ thông minh và điểm nhấn thẩm mỹ cho không gian phòng khách của bạn. Với thiết kế tối giản, đường nét vuông vắn, Aris 1m4 dễ dàng hòa nhập vào nhiều phong cách nội thất khác nhau, từ Scandinavian ấm cúng đến Minimalism tinh tế.\n\nSản phẩm được chế tác tỉ mỉ từ gỗ công nghiệp MDF phủ Melamine cao cấp, đảm bảo độ bền bỉ, chống trầy xước và dễ dàng vệ sinh. Mặt kệ rộng rãi với chiều dài 1m4 thoải mái đặt các loại tivi màn hình lớn, đi kèm là các ngăn kéo và hộc tủ chứa đồ giúp bạn sắp xếp gọn gàng các thiết bị giải trí, sách báo hay đồ dùng cá nhân. Thiết kế không tay nắm tạo nên vẻ đẹp liền mạch, hiện đại, đồng thời đảm bảo an toàn, đặc biệt với gia đình có trẻ nhỏ.\n\nKệ tivi Aris 1m4 không chỉ là một món đồ nội thất đơn thuần mà còn là một giải pháp thông minh giúp tối ưu hóa không gian và nâng tầm trải nghiệm giải trí tại gia. Sản phẩm phù hợp với nhiều không gian phòng khách khác nhau, đặc biệt là các căn hộ chung cư, nhà phố có diện tích vừa và nhỏ. Với Aris 1m4, bạn có thể dễ dàng tạo nên một không gian phòng khách gọn gàng, ngăn nắp và đầy phong cách.',8,'https://goxinh.com.vn/image/cache/Ke-tivi/z3791185610250_91d9732acd70d49b541e5f606f96c6bf-500x500.jpg;https://goxinh.com.vn/image/cache/Ke-tivi/z3791185588384_cb4115d551ebd60ebcf685e486a68ca3-500x500.jpg;https://goxinh.com.vn/image/cache/Ke-tivi/z3791185577322_69b18f08c6524bb3407222bed3314fe3-500x500.jpg',1599000.00,1,'2025-07-08 20:33:53.048062','2025-07-08 20:36:30.209973'),(28,'Bàn Trang Điểm Nhập Khẩu - GX003','Bàn trang điểm nhập khẩu GX003 là sự kết hợp hoàn hảo giữa vẻ đẹp tinh tế, sang trọng và tính tiện dụng cao, mang đến trải nghiệm làm đẹp đẳng cấp cho không gian phòng ngủ của bạn. Thiết kế của GX003 mang đậm phong cách tân cổ điển với những đường nét mềm mại, uyển chuyển, được trau chuốt tỉ mỉ đến từng chi tiết. Mặt bàn rộng rãi, được làm từ gỗ công nghiệp cao cấp phủ Melamine chống trầy xước, dễ dàng vệ sinh và bảo quản. Các ngăn kéo được thiết kế thông minh, tối ưu hóa không gian lưu trữ mỹ phẩm, phụ kiện cá nhân và các vật dụng cần thiết. Gương soi lớn, sắc nét, giúp bạn dễ dàng trang điểm và kiểm tra vẻ ngoài một cách hoàn hảo. Phần chân bàn được làm từ gỗ tự nhiên, được xử lý chống mối mọt, cong vênh, đảm bảo độ bền chắc và tuổi thọ lâu dài. Công nghệ sản xuất hiện đại, kết hợp với quy trình kiểm tra chất lượng nghiêm ngặt, đảm bảo mỗi sản phẩm đều đạt tiêu chuẩn cao nhất. GX003 không chỉ là một chiếc bàn trang điểm đơn thuần mà còn là một món đồ nội thất trang trí, góp phần tô điểm thêm vẻ đẹp sang trọng và quyến rũ cho phòng ngủ của bạn. Với kích thước vừa phải, GX003 phù hợp với nhiều không gian phòng ngủ khác nhau, từ căn hộ nhỏ đến biệt thự rộng lớn. Sản phẩm đặc biệt phù hợp với phong cách nội thất tân cổ điển, vintage và hiện đại tối giản. Sở hữu bàn trang điểm GX003, bạn không chỉ có một không gian làm đẹp lý tưởng mà còn tận hưởng sự thoải mái, tiện nghi và cảm giác thư thái mỗi ngày.',18,'https://goxinh.com.vn/image/cache/Ban-trang-diem/Nhập Khẩu /GX02/z6043704269339_ca63343660db43550c61064129457b47-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-trang-diem/Nhập Khẩu /GX02/z6043704285315_810311d5d12b3198e38aa2ac48db76c3-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-trang-diem/Nhập Khẩu /GX02/z6043704269339_ca63343660db43550c61064129457b47-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-trang-diem/Nhập Khẩu / GX003/z6463795604661_ec3f9f4cbcd93a0d7d3b09d11bcfb4ae-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-trang-diem/Nhập Khẩu /GX02/z6043704274576_03b2531a9802b65454847f62cf605991-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-trang-diem/Nhập Khẩu / GX003/z6463795617534_55af937d8f6bc86434b41d430206f1dc-500x500.jpg',2850000.00,1,'2025-07-08 20:33:53.051682','2025-07-08 20:33:53.051682'),(29,'Bàn Trang Điểm Nhập Khẩu Baleiya màu trắng VN26','Bàn trang điểm nhập khẩu Baleiya màu trắng VN26 là sự kết hợp hoàn hảo giữa vẻ đẹp tinh tế và công năng sử dụng tối ưu, mang đến không gian trang điểm sang trọng và tiện nghi cho phái đẹp. Thiết kế mang đậm phong cách tân cổ điển với những đường nét mềm mại, uyển chuyển, tạo nên sự thanh lịch và quý phái. Màu trắng trang nhã giúp bàn trang điểm dễ dàng hòa hợp với nhiều phong cách nội thất khác nhau, từ hiện đại tối giản đến cổ điển lãng mạn. \n\nMặt bàn rộng rãi cung cấp không gian thoải mái để bày trí mỹ phẩm, dụng cụ trang điểm và các vật dụng cá nhân khác. Ngăn kéo được thiết kế tỉ mỉ, giúp bạn sắp xếp đồ đạc một cách gọn gàng và ngăn nắp. Gương soi chất lượng cao mang lại hình ảnh chân thực và sắc nét, hỗ trợ bạn trang điểm một cách dễ dàng và chính xác. \n\nBàn trang điểm Baleiya VN26 được chế tác từ chất liệu gỗ công nghiệp cao cấp, đảm bảo độ bền đẹp và khả năng chống mối mọt, cong vênh trong quá trình sử dụng. Bề mặt phủ lớp sơn trắng mịn, dễ dàng lau chùi và vệ sinh. Các chi tiết kim loại được gia công tỉ mỉ, mang đến vẻ đẹp hoàn thiện và sang trọng cho sản phẩm. \n\nVới kích thước vừa phải, bàn trang điểm Baleiya VN26 phù hợp với nhiều không gian phòng ngủ khác nhau, từ căn hộ nhỏ đến biệt thự rộng lớn. Sản phẩm không chỉ là một món đồ nội thất hữu ích mà còn là điểm nhấn trang trí, góp phần tô điểm cho không gian sống thêm phần tinh tế và đẳng cấp. Sở hữu bàn trang điểm Baleiya VN26, bạn sẽ có một góc làm đẹp lý tưởng, nơi bạn có thể thỏa sức sáng tạo và tận hưởng những phút giây thư giãn sau một ngày dài.',18,'https://goxinh.com.vn/image/cache/Ban-trang-diem/Nhập Khẩu /Bảo Yến/z4798293672589_811465bd0ce6d03aa9d9893f3b62f969-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-trang-diem/Nhập Khẩu /Bảo Yến/z4816301753987_0b5c008276c995702d3da8e412f9733d-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-trang-diem/Nhập Khẩu /Bảo Yến/z4816301742391_4d794500c32252b7291a4177728e6b58-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-trang-diem/Nhập Khẩu /Bảo Yến/z4798293672589_811465bd0ce6d03aa9d9893f3b62f969-500x500.jpg;https://goxinh.com.vn/image/cache/Ban-trang-diem/Nhập Khẩu /Bảo Yến/z4816301747668_d281e720b1bd771f32af760345c1f987-500x500.jpg',2950000.00,1,'2025-07-08 20:33:53.052670','2025-07-08 20:33:53.052670'),(30,'Tủ thuốc có móc treo','Tủ thuốc có móc treo là giải pháp lưu trữ thông minh và tiện lợi cho mọi gia đình. Thiết kế tối giản, hiện đại, tủ thuốc không chỉ là nơi cất giữ các loại thuốc men, dụng cụ y tế mà còn góp phần tô điểm thêm vẻ đẹp cho không gian sống của bạn. \n\nTủ được thiết kế dạng hình hộp chữ nhật, với cánh tủ mở ra dễ dàng, bên trong là các ngăn kệ được bố trí khoa học, giúp bạn phân loại và sắp xếp thuốc một cách ngăn nắp. Điểm nhấn đặc biệt của tủ là hệ thống móc treo được gắn bên ngoài, cho phép bạn treo các vật dụng cá nhân như chìa khóa, khẩu trang, hoặc các dụng cụ y tế nhỏ gọn, tiện lợi khi cần thiết. \n\nTủ thuốc được sản xuất từ chất liệu gỗ công nghiệp MDF phủ Melamine cao cấp, đảm bảo độ bền đẹp, chống ẩm mốc và dễ dàng vệ sinh. Công nghệ sản xuất hiện đại, tỉ mỉ trong từng chi tiết, mang đến sản phẩm chất lượng cao, an toàn cho người sử dụng. \n\nTủ thuốc có móc treo phù hợp với nhiều phong cách nội thất khác nhau, từ hiện đại, tối giản đến phong cách Bắc Âu ấm cúng. Sản phẩm đặc biệt hữu ích cho các gia đình có trẻ nhỏ hoặc người lớn tuổi, giúp việc quản lý và sử dụng thuốc trở nên dễ dàng và an toàn hơn. Kích thước nhỏ gọn của tủ cho phép bạn dễ dàng lắp đặt ở nhiều vị trí khác nhau trong nhà, như phòng tắm, phòng ngủ, hoặc hành lang. \n\nSở hữu tủ thuốc có móc treo, bạn không chỉ có một không gian lưu trữ thuốc gọn gàng, khoa học mà còn đảm bảo sức khỏe cho cả gia đình, đồng thời tạo điểm nhấn thẩm mỹ cho ngôi nhà của bạn.',60,'https://goxinh.com.vn/image/cache/tu-thuoc/z2068933504712_80e3a478b55372b714e2798645355a44-500x500.jpg',310000.00,1,'2025-07-08 20:33:53.053720','2025-07-08 20:33:53.053720'),(31,'Tủ thuốc góc','Tủ thuốc góc là giải pháp lý tưởng để tối ưu hóa không gian phòng tắm hoặc bất kỳ góc nhỏ nào trong nhà bạn. Với thiết kế thông minh, tủ thuốc này không chỉ cung cấp không gian lưu trữ an toàn cho các loại thuốc men, dụng cụ y tế mà còn mang đến vẻ đẹp thẩm mỹ tinh tế cho không gian sống.\n\nKiểu dáng góc cạnh của tủ được thiết kế để vừa vặn với các góc tường, tận dụng tối đa diện tích vốn có. Mặt trước tủ thường được trang bị cánh cửa kính trong suốt hoặc mờ, giúp bạn dễ dàng quan sát và tìm kiếm các vật dụng bên trong. Bên trong tủ được chia thành nhiều ngăn kệ với độ cao khác nhau, phù hợp để chứa các loại thuốc, bông băng, cồn, nhiệt kế và các vật dụng cá nhân khác.\n\nTủ thuốc góc được chế tạo từ các vật liệu chất lượng cao như gỗ tự nhiên (gỗ sồi, gỗ thông) hoặc gỗ công nghiệp (MDF, HDF) phủ melamine hoặc sơn PU chống ẩm mốc. Công nghệ sản xuất hiện đại đảm bảo độ bền bỉ, chắc chắn và khả năng chịu lực tốt. Bản lề và tay nắm cửa được lựa chọn kỹ lưỡng, đảm bảo sự êm ái và độ bền trong quá trình sử dụng.\n\nTính năng nổi bật của tủ thuốc góc nằm ở khả năng tiết kiệm không gian, giúp phòng tắm hoặc không gian sống trở nên gọn gàng và ngăn nắp hơn. Thiết kế đa năng cho phép bạn sử dụng tủ không chỉ để lưu trữ thuốc men mà còn có thể dùng để đựng các vật dụng cá nhân khác như mỹ phẩm, đồ dùng vệ sinh cá nhân.\n\nTủ thuốc góc phù hợp với nhiều phong cách nội thất khác nhau, từ hiện đại tối giản đến cổ điển sang trọng. Với màu sắc đa dạng và kiểu dáng tinh tế, tủ thuốc góc sẽ là điểm nhấn ấn tượng cho không gian sống của bạn. Sản phẩm mang đến sự tiện lợi, an toàn và thẩm mỹ, giúp bạn chăm sóc sức khỏe gia đình một cách tốt nhất.',60,'https://goxinh.com.vn/image/cache/tu-thuoc/z2068933519391_75df17e5f0fbc3267240299e874cef50-500x500.jpg',490000.00,1,'2025-07-08 20:33:53.054834','2025-07-08 20:33:53.054834'),(32,'Tủ thuốc mái bằng có hộc','Tủ thuốc mái bằng có hộc là giải pháp lưu trữ thông minh và thẩm mỹ cho mọi gia đình. Thiết kế tối giản với mái bằng thanh lịch, tủ thuốc dễ dàng hòa nhập vào nhiều phong cách nội thất khác nhau, từ hiện đại đến tân cổ điển. Điểm nhấn của sản phẩm là hộc tủ nhỏ gọn phía dưới, tăng thêm không gian lưu trữ cho những vật dụng cá nhân hoặc đồ dùng y tế cần thiết. Tủ được sản xuất từ vật liệu gỗ công nghiệp cao cấp, đảm bảo độ bền bỉ và khả năng chống ẩm mốc tốt. Bề mặt phủ Melamine giúp sản phẩm dễ dàng vệ sinh và duy trì vẻ đẹp lâu dài. Các chi tiết bản lề và tay nắm được lựa chọn kỹ lưỡng, đảm bảo độ chắc chắn và an toàn khi sử dụng. Bên trong tủ được chia thành nhiều ngăn, giúp bạn dễ dàng sắp xếp và phân loại thuốc men, dụng cụ y tế một cách khoa học. Với kích thước nhỏ gọn, tủ thuốc mái bằng có hộc phù hợp với nhiều không gian khác nhau, từ phòng tắm, phòng ngủ đến phòng khách. Sản phẩm không chỉ là nơi lưu trữ thuốc men mà còn là một món đồ nội thất trang trí, mang đến vẻ đẹp tinh tế và tiện nghi cho ngôi nhà của bạn. Tủ thuốc mái bằng có hộc phù hợp với phong cách nội thất tối giản, hiện đại, Bắc Âu (Scandinavian), và cả phong cách tân cổ điển. Lợi ích của sản phẩm là giúp người dùng dễ dàng tìm kiếm và sử dụng thuốc men, đảm bảo an toàn và vệ sinh cho các thành viên trong gia đình, đồng thời tăng tính thẩm mỹ cho không gian sống.',60,'https://goxinh.com.vn/image/cache/tu-thuoc/tu_thuoc_mai_bang_khong_hoc-500x500.jpg',430000.00,1,'2025-07-08 20:33:53.056243','2025-07-08 20:33:53.056243'),(33,'Tủ thuốc mái bằng không hộc','Tủ thuốc mái bằng không hộc là giải pháp lưu trữ y tế gia đình tinh tế và tiện dụng. Thiết kế tối giản với mái bằng thanh lịch, tập trung vào công năng sử dụng và tính thẩm mỹ hiện đại. Tủ không có hộc kéo, thay vào đó là các ngăn kệ bên trong, tối ưu hóa không gian lưu trữ cho nhiều loại thuốc, dụng cụ y tế và vật tư cá nhân khác. Cánh tủ có khóa an toàn, đảm bảo thuốc được bảo quản an toàn, đặc biệt là trong gia đình có trẻ nhỏ. Chất liệu gỗ tự nhiên hoặc gỗ công nghiệp cao cấp được xử lý chống ẩm mốc, mối mọt, đảm bảo độ bền và tuổi thọ sản phẩm. Bề mặt tủ được sơn phủ kỹ lưỡng, dễ dàng vệ sinh, lau chùi. Tủ thuốc mái bằng không hộc không chỉ là một vật dụng cần thiết mà còn là điểm nhấn trang trí cho không gian phòng tắm, phòng ngủ hoặc phòng khách. Phong cách thiết kế trung tính, dễ dàng phối hợp với nhiều phong cách nội thất khác nhau, từ hiện đại, tối giản đến Scandinavian. Với thiết kế thông minh, tủ giúp bạn dễ dàng phân loại và tìm kiếm thuốc, tiết kiệm thời gian và công sức. Sản phẩm mang đến sự an tâm và tiện lợi cho việc chăm sóc sức khỏe gia đình.',60,'https://goxinh.com.vn/image/cache/tu-thuoc/tu_thuoc_mai_bang_co_hoc-500x500.jpg',420000.00,1,'2025-07-08 20:33:53.057364','2025-07-08 20:33:53.057364'),(34,'Tủ thuốc mái chéo có hộc','Tủ thuốc mái chéo có hộc là sự kết hợp hài hòa giữa nét đẹp truyền thống và công năng hiện đại, mang đến giải pháp lưu trữ an toàn và thẩm mỹ cho không gian sống của bạn. Thiết kế mái chéo độc đáo tạo điểm nhấn khác biệt, gợi nhớ đến kiến trúc nhà ở Việt Nam xưa. Các đường nét được gia công tỉ mỉ, tinh tế, thể hiện sự trau chuốt trong từng chi tiết. Tủ có nhiều ngăn kệ với kích thước khác nhau, đáp ứng nhu cầu sắp xếp đa dạng các loại thuốc, dụng cụ y tế, và vật dụng cá nhân. Hộc tủ được trang bị ray trượt êm ái, giúp thao tác đóng mở dễ dàng và thuận tiện. \n\nChất liệu gỗ tự nhiên được xử lý chống mối mọt, cong vênh, đảm bảo độ bền đẹp theo thời gian. Bề mặt tủ được sơn phủ lớp sơn cao cấp, chống trầy xước, dễ dàng vệ sinh và lau chùi. Tủ thuốc mái chéo có hộc không chỉ là vật dụng cần thiết trong mỗi gia đình mà còn là điểm nhấn trang trí, góp phần tô điểm cho không gian nội thất thêm ấm cúng và sang trọng. Kích thước nhỏ gọn của tủ phù hợp với nhiều không gian khác nhau, từ phòng khách, phòng ngủ đến phòng tắm. \n\nTủ thuốc này đặc biệt phù hợp với phong cách nội thất mang hơi hướng vintage, rustic, hoặc phong cách đồng quê. Nó cũng có thể dễ dàng kết hợp với các phong cách nội thất hiện đại để tạo điểm nhấn độc đáo. Với tủ thuốc mái chéo có hộc, bạn có thể yên tâm bảo quản thuốc men một cách ngăn nắp, khoa học, đồng thời tăng thêm vẻ đẹp thẩm mỹ cho ngôi nhà của mình. Đây là lựa chọn lý tưởng cho những ai yêu thích sự kết hợp giữa truyền thống và hiện đại, giữa công năng và thẩm mỹ.',60,'https://goxinh.com.vn/image/cache/tu-thuoc/tu_thuoc_mai_cheo_co_hoc-500x500.jpg',490000.00,1,'2025-07-08 20:33:53.061074','2025-07-08 20:33:53.061074'),(35,'Tủ thuốc mái chéo không hộc','Tủ thuốc mái chéo không hộc là giải pháp lưu trữ thông minh và thẩm mỹ cho mọi gia đình. Thiết kế mái chéo độc đáo, kết hợp cùng kiểu dáng tối giản, mang đến vẻ đẹp thanh lịch và hiện đại cho không gian. Tủ được chế tác tỉ mỉ, chú trọng đến từng chi tiết nhỏ, đảm bảo độ bền và tính thẩm mỹ cao. Cánh tủ được thiết kế đóng mở dễ dàng, bên trong chia thành các ngăn kệ khoa học, giúp bạn sắp xếp thuốc men và các vật dụng y tế một cách gọn gàng, ngăn nắp. \n\nChất liệu gỗ công nghiệp cao cấp, phủ Melamine chống trầy xước, ẩm mốc, đảm bảo tuổi thọ lâu dài. Công nghệ sản xuất hiện đại giúp bề mặt tủ láng mịn, dễ dàng vệ sinh, lau chùi. Tủ thuốc mái chéo không hộc không chỉ là nơi lưu trữ thuốc men mà còn là điểm nhấn trang trí ấn tượng, phù hợp với nhiều phong cách nội thất khác nhau, từ hiện đại, tối giản đến Bắc Âu. \n\nVới kích thước nhỏ gọn, tủ có thể đặt ở nhiều vị trí khác nhau trong nhà như phòng tắm, phòng khách, phòng ngủ hay hành lang. Sản phẩm mang đến sự tiện lợi, an toàn và thẩm mỹ cho cuộc sống của bạn, giúp bạn dễ dàng tìm kiếm và sử dụng thuốc khi cần thiết, đồng thời góp phần bảo vệ sức khỏe cho cả gia đình.\n\nSản phẩm phù hợp với phong cách nội thất hiện đại, tối giản và Scandinavian. Tủ thuốc này giúp người dùng dễ dàng quản lý và bảo quản thuốc men, tránh xa tầm tay trẻ em, đảm bảo an toàn cho gia đình. Đồng thời, nó còn góp phần tạo nên không gian sống gọn gàng và thẩm mỹ.',60,'https://goxinh.com.vn/image/cache/tu-thuoc/tu_thuoc_mai_cheo_khong_hoc-500x500.jpg',460000.00,1,'2025-07-08 20:33:53.062035','2025-07-08 20:33:53.062035');
